    bypass: bool = false,
    reset_context: bool = false,
    terminate_all: bool = false,
    vertical_causal: bool = false,
    predictable_termination: bool = false,
    segmentation_symbols: bool = false,
};

/// A Maxshift region of interest (A.6.3 RGN, Annex H): a rectangle on the
/// reference grid, half-open, for one component or (null) every component.
pub const RoiRegion = struct {
    component: ?u16 = null,
    x0: u32,
    y0: u32,
    x1: u32,
    y1: u32,
};

/// One component's coding where it departs from COD (A.6.2 COC): its
/// decomposition levels, code-block size, precincts, and code-block style.
/// Unset fields keep the COD value.
pub const ComponentCodingOverride = struct {
    component: u16,
    levels: ?u8 = null,
    block_width: ?u16 = null,
    block_height: ?u16 = null,
    /// When set, `precincts[0..precinct_count]` replaces COD's precincts,
    /// in the order of `LosslessOptions.precincts`.
    precinct_count: ?u8 = null,
    precincts: [33]PrecinctSize = defaultPrecincts(),
    style: ?ComponentBlockStyle = null,
};

pub const LosslessOptions = struct {
    levels: u8 = 5,
    layers: u16 = 1,
    rates: [max_quality_layers]f64 = @splat(0),
    rate_count: u8 = 0,
    progression: ProgressionOrder = .rpcl,
    poc_records: []const PocRecord = &.{},
    poc_in_tile_header: bool = false,
    mct: MultipleComponentTransform = .rct,
    transform: WaveletTransform = .reversible_5_3,
    quantization: QuantizationStyle = .none,
    guard_bits: u8 = 2,
    /// Absolute SIZ image and tile-partition origins. Nonzero values are
    /// currently public only through the sampled planar encoder.
    image_origin_x: u32 = 0,
    image_origin_y: u32 = 0,
    tile_origin_x: u32 = 0,
    tile_origin_y: u32 = 0,
    tile_width: u32 = 4096,
    tile_height: u32 = 4096,
    block_width: u16 = 64,
    block_height: u16 = 64,
    precincts: [33]PrecinctSize = defaultPrecincts(),
    precinct_count: u8 = 3,
    bypass: bool = false,
    reset_context: bool = false,
    terminate_all: bool = false,
    vertical_causal: bool = false,
    predictable_termination: bool = false,
    segmentation_symbols: bool = false,
    sop: bool = true,
    eph: bool = false,
    tlm: bool = true,
    /// Emit PLT packet-length markers. PLT-less output is currently public
    /// only through the bounded sampled single-tile encoder.
    plt: bool = true,
    ppm: bool = false,
    ppt: bool = false,
    tile_part_divisions: ?u8 = 'R',
    threads: u8 = 1,
    emit_temporary_payload_sidecar: bool = false,
    t1_backend: T1Backend = .iso_mq,
    /// Per-component coding written as main-header COC markers. Only the
    /// wide native encoder (`encodeNativeLosslessWithOptions`) carries it;
    /// every other encoder refuses a non-empty list.
    component_coding: []const ComponentCodingOverride = &.{},
    /// Maxshift regions of interest, written as main-header RGN markers by
    /// the wide native encoder only; every other encoder refuses them.
    roi_regions: []const RoiRegion = &.{},

    pub fn precinctForResolution(self: LosslessOptions, resolution: usize) PrecinctSize {
        const count = @as(usize, self.precinct_count);
        if (resolution < count) return self.precincts[resolution];
        return self.precincts[count - 1];
    }
};

pub const EncodeTimings = struct {
    total_ns: u64 = 0,
    color_transform_ns: u64 = 0,
    wavelet_ns: u64 = 0,
    payload_ns: u64 = 0,
    marker_ns: u64 = 0,
    t1_pass_stats: ebcot.EncodePassStats = .{},
};

fn normalizedEncodePrecinctOptions(options: LosslessOptions, levels: u8) LosslessOptions {
    var normalized = options;
    if (options.precinct_count == 0) return normalized;

    const resolution_count = @as(usize, levels) + 1;
    const option_count = @as(usize, options.precinct_count);
    var resolution: usize = 0;
    while (resolution < resolution_count) : (resolution += 1) {
        const cli_resolution = @as(usize, levels) - resolution;
        const source = if (cli_resolution < option_count)
            cli_resolution
        else
            option_count - 1;
        normalized.precincts[resolution] = options.precincts[source];
    }
    normalized.precinct_count = @intCast(resolution_count);
    return normalized;
}

pub const DecodeRegion = struct {
    /// Absolute SIZ reference-grid origin of the requested half-open region.
    x0: u32,
    y0: u32,
    width: u32,
    height: u32,
};

pub const DecodeOptions = struct {
    threads: u8 = 1,
    t1_backend: T1Backend = .iso_mq,
    /// Decode one row-major SIZ tile and return only its clipped image region.
    /// Null selects the complete tile grid.
    tile_index: ?u32 = null,
    /// Decode the absolute SIZ reference-grid rectangle x0/y0/width/height.
    /// The rectangle must be non-empty, contained in the image, and is
    /// mutually exclusive with tile_index.
    reference_region: ?DecodeRegion = null,
    /// Reconstruct only the first N quality layers while still validating the
    /// complete codestream. Zero selects every signalled layer.
    quality_layer_limit: u16 = 0,
    /// Discard this many finest DWT resolution levels during synthesis.
    /// Zero reconstructs the full image; the value must not exceed COD/NL.
    resolution_reduction: u8 = 0,
    /// See `Rgb8Raster`. Null returns 16-bit samples as usual.
    rgb8_raster: ?*Rgb8Raster = null,
};

/// Optional output for an interleaved 8-bit RGB decode: where it applies (a
/// single-tile, full-resolution, uncropped decode with RCT or ICT), the
/// colour transform writes its samples straight into `bytes`, allocated with
/// `prefix_len` free bytes before them and `suffix_len` after (room for a
/// file header and trailer), and the returned image carries no samples.
/// Elsewhere `bytes` stays empty and the image carries its 16-bit samples.
/// The caller frees `bytes` with the decode allocator.
pub const Rgb8Raster = struct {
    prefix_len: usize = 0,
    suffix_len: usize = 0,
    bytes: []u8 = &.{},
};

/// One component window inside a `TileSinkRegion`. Coordinates are absolute
/// reduced component-grid positions, so a sink can place the window without
/// knowing the tile grid, the component sampling factors, or the image origin.
/// `samples` borrows decoder-owned memory: row `index` starts at
/// `index * stride` and is `width` samples long. Subsampling and resolution
/// reduction can collapse a component window even when the tile itself is not
/// empty; such a window reports `width` and `height` as zero together.
pub const TileSinkComponent = struct {
    x0: u32,
    y0: u32,
    width: usize,
    height: usize,
    stride: usize,
    bit_depth: u8,
    samples: []const u16,

    pub fn row(self: TileSinkComponent, index: usize) []const u16 {
        const start = index * self.stride;
        return self.samples[start .. start + self.width];
    }
};

/// One decoded tile handed to a planar tile sink, already intersected with the
/// requested output window and expressed in absolute reduced reference-grid
/// coordinates.
pub const TileSinkRegion = struct {
    tile_index: u32,
    x0: u32,
    y0: u32,
    width: usize,
    height: usize,
    components: []const TileSinkComponent,
};

/// Absolute reduced component-grid extent of one complete output component.
pub const TileSinkComponentLayout = struct {
    x0: u32,
    y0: u32,
    width: usize,
    height: usize,
    bit_depth: u8,
};

/// Complete output geometry, reported once before the first tile so a sink can
/// size its own storage. `x0/y0/width/height` describe the requested reduced
/// reference-grid window; each component layout is that window's own ceil-div
/// intersection. `tiles_selected` is exactly the number of `writeTile` calls
/// that will follow, and `tiles_total` is the complete SIZ tile grid.
pub const TileSinkInfo = struct {
    x0: u32,
    y0: u32,
    width: usize,
    height: usize,
    tiles_total: u64,
    tiles_selected: u64,
    components: []const TileSinkComponentLayout,
};

/// Complete geometry of a banded output, reported once before the first band.
/// Both banded entry points put every component on one common grid, so all
/// component layouts describe the same rectangle and differ only in precision.
/// `bands_total` is exactly the number of `writeBand` calls that will follow.
pub const BandSinkInfo = struct {
    x0: u32,
    y0: u32,
    width: usize,
    height: usize,
    bands_total: u64,
    components: []const TileSinkComponentLayout,
};

/// One horizontal band spanning the full requested width and one complete SIZ
/// tile row, in absolute reduced reference-grid coordinates. Bands are emitted
/// top to bottom, are disjoint, and together cover the window reported by
/// `begin` exactly.
pub const BandSinkRegion = struct {
    band_index: usize,
    x0: u32,
    y0: u32,
    width: usize,
    height: usize,
    components: []const TileSinkComponent,
};

/// Complete geometry of an interleaved RGB output window, reported once before
/// the first tile. The RGB path is fixed at three components on a common grid,
/// so there is no per-component layout; `tiles_selected` is exactly the number
/// of `writeTile` calls that will follow.
pub const RgbTileSinkInfo = struct {
    x0: u32,
    y0: u32,
    width: usize,
    height: usize,
    bit_depth: u8,
    tiles_total: u64,
    tiles_selected: u64,
};

/// One decoded tile of an interleaved RGB raster, already intersected with the
/// requested output window and expressed in absolute reduced reference-grid
/// coordinates. `samples` borrows decoder-owned memory and holds three
/// interleaved samples per pixel; row `index` starts at `index * stride` and is
/// `width * 3` samples long.
pub const RgbTileSinkRegion = struct {
    tile_index: u32,
    x0: u32,
    y0: u32,
    width: usize,
    height: usize,
    stride: usize,
    bit_depth: u8,
    samples: []const u16,

    pub fn row(self: RgbTileSinkRegion, index: usize) []const u16 {
        const start = index * self.stride;
        return self.samples[start .. start + self.width * 3];
    }
};

/// One component window inside a `NativeTileSinkRegion`. `layout` is the
/// component's own precision, signedness, sampling step, and CRG registration,
/// with `x0`/`y0`/`width`/`height` describing this window on the absolute
/// reduced component grid. `samples` borrows decoder-owned memory: row `index`
/// starts at `index * stride` and is `layout.width` samples long. Subsampling
/// and resolution reduction can collapse a window even when the tile itself is
/// not empty; such a window reports `width` and `height` as zero together.
pub const NativeTileSinkComponent = struct {
    layout: NativeComponentLayout,
    stride: usize,
    samples: []const i64,

    pub fn row(self: NativeTileSinkComponent, index: usize) []const i64 {
        const start = index * self.stride;
        return self.samples[start .. start + self.layout.width];
    }
};

/// One decoded tile handed to a native tile sink, already intersected with the
/// requested output window and expressed in absolute reduced reference-grid
/// coordinates.
pub const NativeTileSinkRegion = struct {
    tile_index: u32,
    x0: u32,
    y0: u32,
    width: usize,
    height: usize,
    components: []const NativeTileSinkComponent,
};

/// Complete native output geometry, reported once before the first tile.
/// `x0/y0/width/height` describe the requested reduced reference-grid window,
/// and each component layout is that window's own reduced component grid with
/// its declared precision and signedness. `tiles_selected` is exactly the
/// number of `writeTile` calls that will follow.
pub const NativeTileSinkInfo = struct {
    x0: u32,
    y0: u32,
    width: usize,
    height: usize,
    tiles_total: u64,
    tiles_selected: u64,
    components: []const NativeComponentLayout,
};

pub const DecodeTimings = struct {
    total_ns: u64 = 0,
    sidecar_or_legacy_ns: u64 = 0,
    metadata_ns: u64 = 0,
    packet_catalog_ns: u64 = 0,
    packet_catalog_scan_ns: u64 = 0,
    packet_catalog_header_ns: u64 = 0,
    packet_catalog_finalize_ns: u64 = 0,
    packet_catalog_input_bytes_materialized: u64 = 0,
    packet_catalog_input_bytes_borrowed: u64 = 0,
    block_payload_ns: u64 = 0,
    block_worker_jobs: u64 = 0,
    block_worker_ns_sum: u64 = 0,
    block_worker_ns_max: u64 = 0,
    block_worker_blocks_sum: u64 = 0,
    block_worker_blocks_max: u64 = 0,
    block_worker_payload_sum: u64 = 0,
    block_worker_payload_max: u64 = 0,
    packet_catalog_payload_bytes_materialized: u64 = 0,
    packet_catalog_payload_bytes_retained: u64 = 0,
    packet_catalog_payload_bytes_discarded: u64 = 0,
    t1_skipped_blocks: u64 = 0,
    t1_skipped_payload_bytes: u64 = 0,
    tiles_total: u64 = 0,
    tiles_decoded: u64 = 0,
    tiles_skipped: u64 = 0,
    wavelet_ns: u64 = 0,
    color_transform_ns: u64 = 0,
    t1_pass_stats: ebcot.DecodePassStats = .{},

    fn addStrictBlockWorker(self: *DecodeTimings, stats: StrictBlockWorkerStats) void {
        self.block_worker_jobs += 1;
        self.block_worker_ns_sum += stats.ns;
        self.block_worker_ns_max = @max(self.block_worker_ns_max, stats.ns);
        self.block_worker_blocks_sum += stats.blocks;
        self.block_worker_blocks_max = @max(self.block_worker_blocks_max, stats.blocks);
        self.block_worker_payload_sum += stats.payload_bytes;
        self.block_worker_payload_max = @max(self.block_worker_payload_max, stats.payload_bytes);
        self.t1_skipped_blocks += stats.skipped_blocks;
        self.t1_skipped_payload_bytes += stats.skipped_payload_bytes;
    }
};

const StrictBlockWorkerStats = struct {
    ns: u64 = 0,
    blocks: u64 = 0,
    payload_bytes: u64 = 0,
    skipped_blocks: u64 = 0,
    skipped_payload_bytes: u64 = 0,
};

pub fn encodeLosslessSkeleton(
    allocator: std.mem.Allocator,
    rgb: image.RgbImage,
    requested_levels: u8,
) ![]u8 {
    return encodeLosslessWithOptions(allocator, rgb, .{ .levels = requested_levels });
}

pub fn encodeLosslessWithOptions(
    allocator: std.mem.Allocator,
    rgb: image.RgbImage,
    options: LosslessOptions,
) ![]u8 {
    return encodeLosslessWithOptionsMeasured(allocator, rgb, options, null);
}

pub fn encodeLosslessWithOptionsProfiled(
    allocator: std.mem.Allocator,
    rgb: image.RgbImage,
    options: LosslessOptions,
    timings: *EncodeTimings,
) ![]u8 {
    timings.* = .{};
    return encodeLosslessWithOptionsMeasured(allocator, rgb, options, timings);
}

/// Encodes the narrow ISO/IEC 15444-1 grayscale profile currently supported
/// by z2000: one unsigned component, one tile, reversible 5/3, ISO MQ, RPCL,
/// in-band packet headers, PLT, and optional TLM/SOP/EPH markers. This is
/// the one-plane special case of the planar encoder below.
pub fn encodeLosslessGrayWithOptions(
    allocator: std.mem.Allocator,
    gray: image.GrayImage,
    options: LosslessOptions,
) ![]u8 {
    if (gray.white_is_zero) return CodestreamError.UnsupportedPayload;
    const pixels = std.math.mul(usize, gray.width, gray.height) catch return CodestreamError.ImageTooLarge;
    if (gray.samples.len != pixels) return CodestreamError.InvalidCodestream;
    var plane_slices = [1][]u16{gray.samples};
    return encodeLosslessPlanarWithOptions(allocator, .{
        .allocator = allocator,
        .width = gray.width,
        .height = gray.height,
        .bit_depth = gray.bit_depth,
        .planes = &plane_slices,
    }, options);
}

/// Bounded 1..4-plane reversible profile. Independent layouts use MCT none;
/// four-plane RGBA may use MCT=1, which applies RCT to RGB only and leaves the
/// final alpha plane independent. A single tile stays RPCL with in-band
/// headers and optional R tile-parts/TLM/SOP/EPH; a tile grid goes through
/// `encodeLosslessPlanarMultiTile` and the full multi-tile option set.
pub fn encodeLosslessPlanarWithOptions(
    allocator: std.mem.Allocator,
    planar: color.SamplePlanes,
    options: LosslessOptions,
) ![]u8 {
    if (planar.width == 0 or planar.height == 0 or
        planar.width > std.math.maxInt(u32) or planar.height > std.math.maxInt(u32))
    {
        return CodestreamError.ImageTooLarge;
    }
    if (planar.planes.len == 0 or planar.planes.len > color.max_components) {
        return CodestreamError.UnsupportedPayload;
    }
    var component_bit_depths: [max_codestream_components]u8 = @splat(0);
    var mixed_component_precision = false;
    for (0..planar.planes.len) |component| {
        const component_depth = planar.componentBitDepth(component) orelse return CodestreamError.UnsupportedPayload;
        if (component_depth == 0 or component_depth > 16) return CodestreamError.UnsupportedPayload;
        component_bit_depths[component] = component_depth;
        if (component != 0 and component_depth != component_bit_depths[0]) mixed_component_precision = true;
    }
    if (mixed_component_precision != (planar.bit_depth == 0)) return CodestreamError.UnsupportedPayload;
    if (!mixed_component_precision and planar.bit_depth != component_bit_depths[0]) {
        return CodestreamError.UnsupportedPayload;
    }
    const pixels = std.math.mul(usize, planar.width, planar.height) catch return CodestreamError.ImageTooLarge;
    for (planar.planes, 0..) |plane, component| {
        if (plane.len != pixels) return CodestreamError.InvalidCodestream;
        try validateSamplesFitDepth(plane, component_bit_depths[component]);
    }
    if (options.levels > 32) return CodestreamError.TooManyLevels;
    if (options.layers == 0 or options.layers > max_quality_layers or
        options.rate_count > options.layers or options.threads == 0)
    {
        return CodestreamError.InvalidCodestream;
    }
    try validateBlockSize(options.block_width, options.block_height);
    try validatePrecincts(options);
    try validateRates(options);
    try validateTilePartDivisions(options.tile_part_divisions);
    try validateCodingPath(options);

    const grid = tile_grid.Grid.fromImageSize(
        planar.width,
        planar.height,
        options.tile_width,
        options.tile_height,
    ) catch |err| switch (err) {
        tile_grid.TileGridError.ImageTooLarge => return CodestreamError.ImageTooLarge,
        tile_grid.TileGridError.InvalidImage, tile_grid.TileGridError.InvalidTileGrid => return CodestreamError.InvalidCodestream,
    };
    const rct_alpha = options.mct == .rct and planar.planes.len == 4 and !mixed_component_precision;
    const single_tile_profile = options.transform == .reversible_5_3 and
        options.quantization == .none and
        (options.mct == .none or rct_alpha) and options.progression == .rpcl and
        options.poc_records.len == 0 and !options.poc_in_tile_header and
        !options.ppm and !options.ppt and !options.emit_temporary_payload_sidecar and
        options.t1_backend == .iso_mq and
        (options.tile_part_divisions == null or options.tile_part_divisions == 'R');
    // A tile grid, or a single tile asking for more than the single-tile planar
    // path writes (9/7, another progression order, POC, packed headers, other
    // divisions), goes through the multi-tile machinery; a one-tile grid is a
    // valid input to it. Requests the single-tile path does carry stay there,
    // so their bytes do not change.
    if (!grid.isSingleTile() or !single_tile_profile) {
        var routed = options;
        // One tile in another progression order is written as one part, as
        // the single-tile RGB path does; `R` parts need RPCL. A POC replaces
        // the COD order, and its `R` parts follow the composed sequence.
        if (grid.isSingleTile() and routed.tile_part_divisions == 'R' and routed.progression != .rpcl and
            routed.poc_records.len == 0)
        {
            routed.tile_part_divisions = null;
        }
        return encodeLosslessPlanarMultiTile(allocator, planar, grid, routed, mixed_component_precision);
    }

    const levels = actualDwtLevels(planar.width, planar.height, options.levels);
    const encode_options = normalizedEncodePrecinctOptions(options, levels);

    var scaffold_precincts: [33]packet_plan.Precinct = undefined;
    for (encode_options.precincts[0..encode_options.precinct_count], 0..) |precinct, index| {
        scaffold_precincts[index] = .{ .width = precinct.width, .height = precinct.height };
    }
    const block_style = ebcot.CodeBlockStyle{
        .bypass = encode_options.bypass,
        .reset_context = encode_options.reset_context,
        .terminate_all = encode_options.terminate_all,
        .vertical_causal = encode_options.vertical_causal,
        .predictable_termination = encode_options.predictable_termination,
        .segmentation_symbols = encode_options.segmentation_symbols,
    };
    const scaffold_options = tile_pipeline.PacketScaffoldOptions{
        .layers = encode_options.layers,
        .block_width = encode_options.block_width,
        .block_height = encode_options.block_height,
        .precincts = scaffold_precincts[0..encode_options.precinct_count],
        .rates = encode_options.rates,
        .rate_count = encode_options.rate_count,
    };
    var artifacts = if (rct_alpha)
        try tile_pipeline.buildPlanarRctAlphaRpclEncodeArtifactsIsoMq(
            allocator,
            planar,
            levels,
            scaffold_options,
            block_style,
        )
    else
        try tile_pipeline.buildPlanarRpclEncodeArtifactsIsoMq(
            allocator,
            planar,
            levels,
            scaffold_options,
            block_style,
        );
    defer artifacts.deinit();
    const component_count: u16 = @intCast(planar.planes.len);
    if (artifacts.levels != levels or artifacts.scaffold.components != component_count or
        artifacts.catalog.components != component_count)
    {
        return CodestreamError.InvalidCodestream;
    }

    return assembleSingleTileCodestream(allocator, .{
        .width = planar.width,
        .height = planar.height,
        .bit_depth = planar.bit_depth,
        .component_bit_depths = component_bit_depths,
        .components = component_count,
        .levels = levels,
        .packet_lengths = artifacts.stream.packet_lengths,
        .packet_header_lengths = artifacts.stream.packet_header_lengths,
        .packet_bytes = artifacts.stream.bytes,
    }, encode_options);
}

/// Highest precision the wide encoder accepts: the Part 1 SIZ ceiling. From
/// 29 bits the HH band needs more than 31 magnitude bitplanes, which the
/// native decoder reads through i64 coefficients. Bands are capped at the 37
/// bitplanes QCD can signal, so from 35 bits an image whose coefficients
/// outgrow them is refused rather than truncated.
pub const max_wide_encode_precision: u8 = 38;

/// Reversible encode of native integer components, signed or unsigned, up to
/// `max_wide_encode_precision` bits, through i64 coefficients: an i64 RCT and
/// 5/3 transform, the i64 T1 symbol generator, and the shared scaffold,
/// packet, and codestream writers. One to four components of one precision on
/// the reference grid at the origin, without MCT or with RCT over the first
/// three. Requests the single-tile writer carries (one tile, RPCL, no POC or
/// packed headers) stay there; a tile grid, another progression order, POC,
/// PPM/PPT, and other tile-part divisions go through the multi-tile writer of
/// the main encoder, as `encodeLosslessPlanarWithOptions` routes them.
pub fn encodeNativeLosslessWithOptions(
    allocator: std.mem.Allocator,
    source: NativeSamplePlanes,
    options: LosslessOptions,
) ![]u8 {
    if (!nativeLayoutIsUniform(source) or options.component_coding.len != 0 or options.roi_regions.len != 0) {
        return encodeNativeWideComponentwise(allocator, source, options);
    }
    const component_count = source.planes.len;
    if (component_count == 0 or component_count > color.max_components) return CodestreamError.UnsupportedPayload;
    if (source.reference_x0 != 0 or source.reference_y0 != 0) return CodestreamError.UnsupportedPayload;
    const width: usize = source.reference_x1;
    const height: usize = source.reference_y1;
    if (width == 0 or height == 0) return CodestreamError.InvalidCodestream;
    const precision = source.planes[0].layout.precision;
    if (precision == 0 or precision > max_wide_encode_precision) return CodestreamError.UnsupportedPayload;
    var component_bit_depths: [max_codestream_components]u8 = @splat(0);
    var component_signed: [max_codestream_components]bool = @splat(false);
    for (source.planes, 0..) |plane, component| {
        const layout = plane.layout;
        if (layout.precision != precision or layout.x0 != 0 or layout.y0 != 0 or
            layout.x_step != 1 or layout.y_step != 1 or layout.width != width or layout.height != height or
            plane.samples.len != width * height)
        {
            return CodestreamError.UnsupportedPayload;
        }
        component_bit_depths[component] = precision;
        component_signed[component] = layout.signed;
    }
    if (options.transform != .reversible_5_3 or options.quantization != .none or
        options.emit_temporary_payload_sidecar or options.t1_backend != .iso_mq)
    {
        return CodestreamError.UnsupportedPayload;
    }
    switch (options.mct) {
        .none => {},
        // RCT over the first three components (ISO/IEC 15444-1 G.2); a fourth
        // passes through.
        .rct => if (component_count != 3 and component_count != 4) return CodestreamError.UnsupportedPayload,
        .ict => return CodestreamError.UnsupportedPayload,
    }
    if (options.levels > 32) return CodestreamError.TooManyLevels;
    if (options.layers == 0 or options.layers > max_quality_layers) return CodestreamError.InvalidCodestream;
    try validateBlockSize(options.block_width, options.block_height);
    const grid = tile_grid.Grid.fromImageSize(width, height, options.tile_width, options.tile_height) catch |err| switch (err) {
        tile_grid.TileGridError.ImageTooLarge => return CodestreamError.ImageTooLarge,
        tile_grid.TileGridError.InvalidImage, tile_grid.TileGridError.InvalidTileGrid => return CodestreamError.InvalidCodestream,
    };
    try validateLosslessRequest(grid, options);

    const levels = actualDwtLevels(width, height, options.levels);
    const quantization = try WideReversibleQuantization.forPrecision(precision);

    // ISO B.1.1 DC level shift for unsigned components, then the RCT.
    const planes = try allocator.alloc([]i64, component_count);
    var built: usize = 0;
    defer {
        for (planes[0..built]) |plane| allocator.free(plane);
        allocator.free(planes);
    }
    for (source.planes) |plane| {
        const coefficients = try allocator.dupe(i64, plane.samples);
        planes[built] = coefficients;
        built += 1;
        if (!plane.layout.signed) {
            const shift = @as(i64, 1) << @as(u6, @intCast(precision - 1));
            for (coefficients) |*value| value.* -= shift;
        }
    }
    if (options.mct == .rct) forwardRctWide(planes[0..3]);

    const single_tile_profile = grid.isSingleTile() and options.progression == .rpcl and
        options.poc_records.len == 0 and !options.poc_in_tile_header and
        !options.ppm and !options.ppt and
        (options.tile_part_divisions == null or options.tile_part_divisions == 'R');
    if (!single_tile_profile) {
        var routed = options;
        // One tile in another progression order is written as one part, as
        // the main planar encoder does; `R` parts need RPCL. A POC replaces
        // the COD order, and its `R` parts follow the composed sequence.
        if (grid.isSingleTile() and routed.tile_part_divisions == 'R' and routed.progression != .rpcl and
            routed.poc_records.len == 0)
        {
            routed.tile_part_divisions = null;
        }
        return encodeNativeWideMultiTile(allocator, planes, grid, levels, quantization, .{
            .siz = .{
                .width = @intCast(width),
                .height = @intCast(height),
                .bit_depth = precision,
                .component_bit_depths = component_bit_depths,
                .component_signed = component_signed,
                .components = @intCast(component_count),
                .tile_width = routed.tile_width,
                .tile_height = routed.tile_height,
            },
            .bit_depth = precision,
            .wide_quantization = quantization,
        }, routed);
    }

    const encode_options = normalizedEncodePrecinctOptions(options, levels);
    for (planes) |plane| {
        _ = try wavelet_int.forward53WideOriginThreaded(allocator, plane, width, height, levels, 0, 0, encode_options.threads);
    }
    var scaffold_precincts: [33]packet_plan.Precinct = undefined;
    var scaffold_options = wideScaffoldOptions(encode_options, &scaffold_precincts, component_count, precision, quantization, .rpcl);
    scaffold_options.threads = encode_options.threads;
    var artifacts = try buildWideTileArtifacts(
        allocator,
        try grid.tile(0),
        planes,
        levels,
        scaffold_options,
        wideBlockStyle(encode_options),
    );
    defer artifacts.deinit();
    // Rate targets: the global PCRD sets every block's layer truncations.
    try tile_pipeline.applyGridPcrdTargets(allocator, (&artifacts)[0..1], scaffold_options);

    return assembleSingleTileCodestream(allocator, .{
        .width = width,
        .height = height,
        .bit_depth = precision,
        .component_bit_depths = component_bit_depths,
        .components = @intCast(component_count),
        .levels = levels,
        .packet_lengths = artifacts.stream.packet_lengths,
        .packet_header_lengths = artifacts.stream.packet_header_lengths,
        .packet_bytes = artifacts.stream.bytes,
        .component_signed = component_signed,
        .wide_quantization = quantization,
    }, encode_options);
}

/// Whether `source` fits the wide encoder's uniform path: one to four
/// components of one precision, full resolution on the reference grid at the
/// origin, without CRG registration.
fn nativeLayoutIsUniform(source: NativeSamplePlanes) bool {
    if (source.planes.len == 0 or source.planes.len > color.max_components) return false;
    if (source.reference_x0 != 0 or source.reference_y0 != 0) return false;
    const precision = source.planes[0].layout.precision;
    for (source.planes) |plane| {
        const layout = plane.layout;
        if (layout.precision != precision or layout.x_step != 1 or layout.y_step != 1 or
            layout.x0 != 0 or layout.y0 != 0 or layout.registration_x != 0 or layout.registration_y != 0)
        {
            return false;
        }
    }
    return true;
}

/// The wide encoder's componentwise path, for any Part 1 component layout the
/// uniform path does not carry: up to 16384 components, mixed precision and
/// signedness, SIZ subsampling, a reference-grid origin, and CRG
/// registration. Each component of each tile is transformed and coded on its
/// own (i64 5/3 and T1, as a one-component scaffold on the component's tile
/// rectangle), and the tile's packets are merged into the sampled progression
/// order of B.12, the way `encodeLosslessSampledPlanarWithOptions` does for
/// 8/16-bit planes. QCD carries component 0's wide signalling and QCC every
/// component whose precision differs, with two-byte selectors above 256
/// components. Tiles are written one tile-part each.
fn encodeNativeWideComponentwise(
    allocator: std.mem.Allocator,
    source: NativeSamplePlanes,
    requested: LosslessOptions,
) ![]u8 {
    const component_count = source.planes.len;
    if (component_count == 0 or component_count > max_strict_metadata_components) return CodestreamError.UnsupportedPayload;
    if (source.reference_x1 <= source.reference_x0 or source.reference_y1 <= source.reference_y0) {
        return CodestreamError.InvalidCodestream;
    }
    for (source.planes) |plane| {
        const layout = plane.layout;
        if (layout.precision == 0 or layout.precision > max_wide_encode_precision) return CodestreamError.UnsupportedPayload;
        if (layout.x_step == 0 or layout.y_step == 0) return CodestreamError.InvalidCodestream;
        // The component grid must be the SIZ one (B.2).
        if (layout.x0 != ceilDivU32(source.reference_x0, layout.x_step) or
            layout.y0 != ceilDivU32(source.reference_y0, layout.y_step) or
            layout.width != ceilDivU32(source.reference_x1, layout.x_step) - layout.x0 or
            layout.height != ceilDivU32(source.reference_y1, layout.y_step) - layout.y0 or
            plane.samples.len != try std.math.mul(usize, layout.width, layout.height))
        {
            return CodestreamError.InvalidCodestream;
        }
    }

    var options = requested;
    // Tile-parts are runs of each tile's packet sequence over which the
    // resolution, layer, or component stays the same (B.11).
    const division_supported = if (options.tile_part_divisions) |division|
        division == 'R' or division == 'L' or division == 'C'
    else
        true;
    if (options.transform != .reversible_5_3 or options.quantization != .none or
        options.emit_temporary_payload_sidecar or options.t1_backend != .iso_mq or
        !division_supported or (options.ppm and options.ppt) or (options.ppt and !options.plt))
    {
        return CodestreamError.UnsupportedPayload;
    }
    if (options.poc_in_tile_header and options.poc_records.len == 0) return CodestreamError.InvalidCodestream;
    for (options.roi_regions) |region| {
        if (region.x1 <= region.x0 or region.y1 <= region.y0 or
            region.x0 < source.reference_x0 or region.y0 < source.reference_y0 or
            region.x1 > source.reference_x1 or region.y1 > source.reference_y1)
        {
            return CodestreamError.InvalidCodestream;
        }
        if (region.component) |component| {
            if (component >= component_count) return CodestreamError.InvalidCodestream;
        }
    }
    // POC records carry one-byte component indices here.
    if (options.poc_records.len != 0 and component_count > 256) return CodestreamError.UnsupportedPayload;
    switch (options.mct) {
        .none => {},
        // RCT needs three components on one grid with one precision (G.2).
        .rct => {
            if (component_count < 3) return CodestreamError.UnsupportedPayload;
            const first = source.planes[0].layout;
            for (source.planes[1..3]) |plane| {
                const layout = plane.layout;
                if (layout.precision != first.precision or layout.x_step != first.x_step or layout.y_step != first.y_step) {
                    return CodestreamError.UnsupportedPayload;
                }
            }
        },
        .ict => return CodestreamError.UnsupportedPayload,
    }
    if (options.levels > 32) return CodestreamError.TooManyLevels;
    if (options.layers == 0 or options.layers > max_quality_layers or options.threads == 0 or
        options.rate_count > options.layers)
    {
        return CodestreamError.InvalidCodestream;
    }
    try validateRates(options);
    try validateBlockSize(options.block_width, options.block_height);
    try validatePrecincts(options);
    // The shared style and progression rules; origins and PLT are this
    // writer's own business.
    try validateWideCodingStyle(options);
    options.image_origin_x = source.reference_x0;
    options.image_origin_y = source.reference_y0;

    const grid = tile_grid.Grid.init(.{
        .xsiz = source.reference_x1,
        .ysiz = source.reference_y1,
        .xosiz = source.reference_x0,
        .yosiz = source.reference_y0,
        .xtsiz = options.tile_width,
        .ytsiz = options.tile_height,
        .xtosiz = options.tile_origin_x,
        .ytosiz = options.tile_origin_y,
    }) catch return CodestreamError.InvalidCodestream;
    const tile_count = std.math.cast(usize, grid.tileCount()) orelse return CodestreamError.ImageTooLarge;
    if (tile_count == 0 or tile_count > std.math.maxInt(u16)) return CodestreamError.UnsupportedPayload;
    const reference_width: usize = source.reference_x1 - source.reference_x0;
    const reference_height: usize = source.reference_y1 - source.reference_y0;
    const levels = actualDwtLevels(reference_width, reference_height, options.levels);
    const encode_options = normalizedEncodePrecinctOptions(options, levels);

    // Each component's effective coding: COD's, with its override applied.
    const component_options = try allocator.alloc(LosslessOptions, component_count);
    defer allocator.free(component_options);
    @memset(component_options, options);
    const overridden = try allocator.alloc(bool, component_count);
    defer allocator.free(overridden);
    @memset(overridden, false);
    for (options.component_coding) |override| {
        if (override.component >= component_count or overridden[override.component]) return CodestreamError.InvalidCodestream;
        overridden[override.component] = true;
        applyComponentCodingOverride(&component_options[override.component], override);
    }
    var max_levels = levels;
    for (component_options) |*coding| {
        if (coding.levels > 32) return CodestreamError.TooManyLevels;
        try validateBlockSize(coding.block_width, coding.block_height);
        try validatePrecincts(coding.*);
        try validateWideCodingStyle(coding.*);
        const component_levels = actualDwtLevels(reference_width, reference_height, coding.levels);
        coding.* = normalizedEncodePrecinctOptions(coding.*, component_levels);
        coding.levels = component_levels;
        max_levels = @max(max_levels, component_levels);
    }

    const quantizations = try allocator.alloc(WideReversibleQuantization, component_count);
    defer allocator.free(quantizations);
    for (source.planes, quantizations) |plane, *quantization| {
        quantization.* = try WideReversibleQuantization.forPrecision(plane.layout.precision);
    }

    // ISO B.1.1 DC level shift for unsigned components, then the RCT.
    const planes = try allocator.alloc([]i64, component_count);
    var shifted: usize = 0;
    defer {
        for (planes[0..shifted]) |plane| allocator.free(plane);
        allocator.free(planes);
    }
    for (source.planes) |plane| {
        const coefficients = try allocator.dupe(i64, plane.samples);
        planes[shifted] = coefficients;
        shifted += 1;
        if (!plane.layout.signed) {
            const shift = @as(i64, 1) << @as(u6, @intCast(plane.layout.precision - 1));
            for (coefficients) |*value| value.* -= shift;
        }
    }
    if (options.mct == .rct) forwardRctWide(planes[0..3]);

    // Every (tile, component) pair is an independent job.
    const job_count = try std.math.mul(usize, tile_count, component_count);
    const artifacts = try allocator.alloc(tile_pipeline.TileRpclEncodeArtifacts, job_count);
    defer allocator.free(artifacts);
    const initialized = try allocator.alloc(bool, job_count);
    defer allocator.free(initialized);
    @memset(initialized, false);
    defer for (artifacts, initialized) |*artifact, is_initialized| {
        if (is_initialized) artifact.deinit();
    };
    const regions = try allocator.alloc([]i64, job_count);
    @memset(regions, &.{});
    defer {
        for (regions) |region| allocator.free(region);
        allocator.free(regions);
    }
    const masks = try allocator.alloc([]bool, job_count);
    @memset(masks, &.{});
    defer {
        for (masks) |mask| allocator.free(mask);
        allocator.free(masks);
    }
    const background = try allocator.alloc(u64, job_count);
    defer allocator.free(background);
    @memset(background, 0);
    const roi_shifts = try allocator.alloc(u8, component_count);
    defer allocator.free(roi_shifts);
    @memset(roi_shifts, 0);

    var next_job = std.atomic.Value(usize).init(0);
    const worker_count = @max(@as(usize, 1), @min(@as(usize, options.threads), job_count));
    const jobs = try allocator.alloc(WideComponentTileJob, worker_count);
    defer allocator.free(jobs);
    for (jobs) |*job| {
        job.* = .{
            .allocator = allocator,
            .source = source,
            .planes = planes,
            .quantizations = quantizations,
            .grid = grid,
            .component_options = component_options,
            .roi_regions = options.roi_regions,
            .regions = regions,
            .masks = masks,
            .background = background,
            .roi_shifts = roi_shifts,
            .block_threads = @intCast(@max(1, @as(usize, options.threads) / worker_count)),
            .stage = .transform,
            .artifacts = artifacts,
            .initialized = initialized,
            .next_job = &next_job,
        };
    }
    const threads = try allocator.alloc(std.Thread, worker_count - 1);
    defer allocator.free(threads);
    try runWideComponentJobs(jobs, &next_job, job_count, threads);

    // Maxshift (H.1): s with every background magnitude of the component
    // below 2^s, so the decoder tells ROI from background by magnitude alone.
    // The smallest such s decodes exactly in z2000 and Kakadu 8.4.1, but
    // OpenJPEG 2.5.4 and Grok 20.4.12 take a background magnitude of at
    // least 2^(s-1) for ROI, so s carries one more bit. Bands then carry
    // Mb + s bitplanes, at most 37.
    for (roi_shifts, 0..) |*shift, component| {
        if (!componentHasRoi(options.roi_regions, component)) continue;
        var largest: u64 = 0;
        var tile: usize = 0;
        while (tile < tile_count) : (tile += 1) largest = @max(largest, background[tile * component_count + component]);
        const bits: u8 = @intCast(64 - @clz(largest));
        shift.* = bits + 1;
        var deepest: u8 = 0;
        for (quantizations[component].bitplanes) |bitplanes| deepest = @max(deepest, bitplanes);
        if (@as(u16, deepest) + shift.* > ebcot.max_wide_magnitude_bitplanes) return CodestreamError.UnsupportedPayload;
    }
    for (jobs) |*job| job.stage = .code;
    try runWideComponentJobs(jobs, &next_job, job_count, threads);
    for (initialized) |is_initialized| {
        if (!is_initialized) return CodestreamError.InvalidCodestream;
    }

    // Rate targets: one slope threshold over every block of every
    // tile-component, before the tiles' packets are merged.
    if (encode_options.rate_count != 0) {
        var pcrd_precincts: [33]packet_plan.Precinct = undefined;
        try tile_pipeline.applyGridPcrdTargets(
            allocator,
            artifacts,
            wideScaffoldOptions(encode_options, &pcrd_precincts, 1, source.planes[0].layout.precision, quantizations[0], .rpcl),
        );
    }

    // A progression without POC is the one-record schedule over everything.
    const progression_record = [_]poc.Record{.{
        .resolution_start = 0,
        .component_start = 0,
        .layer_end = encode_options.layers,
        .resolution_end = max_levels + 1,
        .component_end = @intCast(component_count),
        .progression = @fromBackingInt(@intCast(@backingInt(encode_options.progression))),
    }};
    const schedule: []const poc.Record = if (encode_options.poc_records.len != 0)
        encode_options.poc_records
    else if (encode_options.progression == .rpcl)
        &.{}
    else
        &progression_record;

    const sampled_plans = try allocator.alloc(packet_plan.SampledComponentPlan, component_count);
    defer allocator.free(sampled_plans);
    const streams = try allocator.alloc(SampledTilePacketStream, tile_count);
    defer allocator.free(streams);
    var merged: usize = 0;
    defer for (streams[0..merged]) |*stream| stream.deinit();
    while (merged < tile_count) : (merged += 1) {
        const tile_artifacts = artifacts[merged * component_count ..][0..component_count];
        for (tile_artifacts, sampled_plans, source.planes) |artifact, *plan, plane| {
            plan.* = .{ .plan = artifact.scaffold.plan, .xrsiz = plane.layout.x_step, .yrsiz = plane.layout.y_step };
        }
        streams[merged] = try mergeSampledComponentPacketStreams(
            allocator,
            try grid.tile(@intCast(merged)),
            tile_artifacts,
            sampled_plans,
            encode_options.layers,
            schedule,
        );
    }

    const main_header = try wideComponentwiseMainHeaderBytes(allocator, source, quantizations, levels, encode_options, component_options, roi_shifts);
    defer allocator.free(main_header);
    // POC resolution indices reach the deepest component.
    if (encode_options.tile_part_divisions) |division| {
        const runs = try allocator.alloc(std.ArrayList(usize), tile_count);
        var runs_built: usize = 0;
        defer {
            for (runs[0..runs_built]) |*tile_runs| tile_runs.deinit(allocator);
            allocator.free(runs);
        }
        const run_slices = try allocator.alloc([]const usize, tile_count);
        defer allocator.free(run_slices);
        for (streams, runs, run_slices) |stream, *tile_runs, *slice| {
            tile_runs.* = .empty;
            runs_built += 1;
            try appendPocKeyRuns(allocator, tile_runs, stream.sequence, division);
            slice.* = tile_runs.items;
        }
        return writeSampledTilePartsCodestream(allocator, streams, run_slices, main_header, @intCast(component_count), max_levels, encode_options);
    }
    if (grid.isSingleTile()) {
        return writeSampledSingleTileCodestream(allocator, main_header, @intCast(component_count), max_levels, streams[0], encode_options);
    }
    return writeSampledMultiTileCodestream(allocator, streams, main_header, @intCast(component_count), max_levels, encode_options);
}

fn applyComponentCodingOverride(coding: *LosslessOptions, override: ComponentCodingOverride) void {
    if (override.levels) |levels| coding.levels = levels;
    if (override.block_width) |width| coding.block_width = width;
    if (override.block_height) |height| coding.block_height = height;
    if (override.precinct_count) |count| {
        coding.precinct_count = count;
        coding.precincts = override.precincts;
    }
    if (override.style) |style| {
        coding.bypass = style.bypass;
        coding.reset_context = style.reset_context;
        coding.terminate_all = style.terminate_all;
        coding.vertical_causal = style.vertical_causal;
        coding.predictable_termination = style.predictable_termination;
        coding.segmentation_symbols = style.segmentation_symbols;
    }
}

/// The shared style and progression rules of `validateCodingPath`; origins,
/// PLT, and per-component coding are the componentwise writer's own business.
fn validateWideCodingStyle(options: LosslessOptions) !void {
    var check = options;
    check.image_origin_x = 0;
    check.image_origin_y = 0;
    check.tile_origin_x = 0;
    check.tile_origin_y = 0;
    check.plt = true;
    check.component_coding = &.{};
    check.roi_regions = &.{};
    try validateCodingPath(check);
}

/// Whether a component's effective coding is COD's, so it needs no COC.
fn wideCodingMatchesCod(coding: LosslessOptions, cod: LosslessOptions, cod_levels: u8) bool {
    if (coding.levels != cod_levels or coding.block_width != cod.block_width or
        coding.block_height != cod.block_height or codeBlockStyle(coding) != codeBlockStyle(cod) or
        (coding.precinct_count > 0) != (cod.precinct_count > 0))
    {
        return false;
    }
    if (cod.precinct_count == 0) return true;
    for (0..@as(usize, cod_levels) + 1) |resolution| {
        if (precinctByte(coding.precinctForResolution(resolution)) != precinctByte(cod.precinctForResolution(resolution))) {
            return false;
        }
    }
    return true;
}

/// COC (A.6.2) with one component's decomposition levels, code-block size
/// and style, transform, and precincts; the selector takes two bytes when
/// the codestream has more than 256 components.
fn appendCocForComponent(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    component: u16,
    two_byte_selector: bool,
    coding: LosslessOptions,
) !void {
    const uses_precincts = coding.precinct_count > 0;
    const selector_bytes: u16 = if (two_byte_selector) 2 else 1;
    const precinct_bytes: u16 = if (uses_precincts) @as(u16, coding.levels) + 1 else 0;
    try appendMarker(allocator, out, .coc);
    try appendU16Be(allocator, out, 2 + selector_bytes + 1 + 5 + precinct_bytes);
    if (two_byte_selector) {
        try appendU16Be(allocator, out, component);
    } else {
        try out.append(allocator, @intCast(component));
    }
    try out.append(allocator, if (uses_precincts) 0x01 else 0x00);
    try out.append(allocator, coding.levels);
    try out.append(allocator, codeBlockExponent(coding.block_width));
    try out.append(allocator, codeBlockExponent(coding.block_height));
    try out.append(allocator, codeBlockStyle(coding));
    try out.append(allocator, @backingInt(coding.transform));
    if (uses_precincts) {
        for (0..@as(usize, coding.levels) + 1) |resolution| {
            try out.append(allocator, precinctByte(coding.precinctForResolution(resolution)));
        }
    }
}

const WideComponentTileJob = struct {
    allocator: std.mem.Allocator,
    source: NativeSamplePlanes,
    planes: []const []const i64,
    quantizations: []const WideReversibleQuantization,
    grid: tile_grid.Grid,
    /// Each component's effective coding, with its own decomposition levels.
    component_options: []const LosslessOptions,
    roi_regions: []const RoiRegion,
    /// Per (tile, component) job: the transformed coefficients, its ROI mask
    /// (empty without ROI), and the largest background magnitude, kept from
    /// the transform stage for the coding stage when a ROI needs the
    /// component-wide shift first.
    regions: [][]i64,
    masks: [][]bool,
    background: []u64,
    /// Per component Maxshift upshift, set between the stages.
    roi_shifts: []const u8,
    /// Code-block workers per tile-component: the threads the job workers
    /// leave over.
    block_threads: u8 = 1,
    stage: Stage,
    artifacts: []tile_pipeline.TileRpclEncodeArtifacts,
    initialized: []bool,
    next_job: *std.atomic.Value(usize),
    precincts: [33]packet_plan.Precinct = undefined,
    result: anyerror!void = {},

    const Stage = enum { transform, code };

    fn run(self: *WideComponentTileJob) void {
        while (true) {
            const index = self.next_job.fetchAdd(1, .monotonic);
            if (index >= self.artifacts.len) return;
            const outcome = switch (self.stage) {
                .transform => self.transform(index),
                .code => self.code(index),
            };
            outcome catch |err| {
                self.result = err;
                // Stop the other workers at their next job.
                self.next_job.store(self.artifacts.len, .monotonic);
                return;
            };
        }
    }

    fn componentRect(self: *const WideComponentTileJob, index: usize) !struct { tile: tile_grid.Tile, rect: tile_grid.Rect } {
        const component = index % self.planes.len;
        const tile = try self.grid.tile(@intCast(index / self.planes.len));
        const layout = self.source.planes[component].layout;
        return .{ .tile = tile, .rect = .{
            .x0 = ceilDivU32(tile.rect.x0, layout.x_step),
            .y0 = ceilDivU32(tile.rect.y0, layout.y_step),
            .x1 = ceilDivU32(tile.rect.x1, layout.x_step),
            .y1 = ceilDivU32(tile.rect.y1, layout.y_step),
        } };
    }

    /// Cuts the tile-component out of its plane, runs the i64 5/3, and, for a
    /// component with a ROI, marks the ROI coefficients and records the
    /// largest background magnitude.
    fn transform(self: *WideComponentTileJob, index: usize) !void {
        const allocator = self.allocator;
        const component = index % self.planes.len;
        const layout = self.source.planes[component].layout;
        const placed = try self.componentRect(index);
        const rect = placed.rect;
        // A tile that holds no sample of a subsampled component would need an
        // empty component tile, which the scaffold does not build.
        if (rect.x1 <= rect.x0 or rect.y1 <= rect.y0) return CodestreamError.UnsupportedPayload;
        const width: usize = rect.width();
        const height: usize = rect.height();
        const region = try allocator.alloc(i64, try std.math.mul(usize, width, height));
        self.regions[index] = region;
        const plane = self.planes[component];
        for (0..height) |row| {
            const start = (@as(usize, rect.y0 - layout.y0) + row) * layout.width + (rect.x0 - layout.x0);
            @memcpy(region[row * width ..][0..width], plane[start..][0..width]);
        }
        const coding = self.component_options[component];
        const achieved = try wavelet_int.forward53WideOriginThreaded(allocator, region, width, height, coding.levels, rect.x0, rect.y0, self.block_threads);
        if (achieved != coding.levels) return CodestreamError.InvalidCodestream;

        if (!componentHasRoi(self.roi_regions, component)) return;
        const mask = try allocator.alloc(bool, region.len);
        self.masks[index] = mask;
        try markWideRoiCoefficients(allocator, mask, rect, coding.levels, layout, self.roi_regions, component);
        var background: u64 = 0;
        for (region, mask) |coefficient, in_roi| {
            if (!in_roi) background = @max(background, @abs(coefficient));
        }
        self.background[index] = background;
    }

    /// Applies the component's Maxshift upshift to its ROI coefficients and
    /// codes the tile-component.
    fn code(self: *WideComponentTileJob, index: usize) !void {
        const component = index % self.planes.len;
        const layout = self.source.planes[component].layout;
        const placed = try self.componentRect(index);
        const region = self.regions[index];
        const shift = self.roi_shifts[component];
        if (shift != 0) {
            // Every shifted magnitude stays below 2^37, the Part 1 ceiling.
            const limit = @as(u64, 1) << @intCast(ebcot.max_wide_magnitude_bitplanes - shift);
            for (region, self.masks[index]) |*coefficient, in_roi| {
                if (!in_roi) continue;
                if (@abs(coefficient.*) >= limit) return CodestreamError.UnsupportedPayload;
                coefficient.* <<= @intCast(shift);
            }
        }
        const coding = self.component_options[component];
        var scaffold_options = wideScaffoldOptions(coding, &self.precincts, 1, layout.precision, self.quantizations[component], .rpcl);
        scaffold_options.threads = self.block_threads;
        if (shift != 0) {
            for (&scaffold_options.nominal_bitplanes.?) |*level| {
                for (level) |*bitplanes| bitplanes.* += shift;
            }
            scaffold_options.roi_shift = shift;
        }
        const component_tile = tile_grid.Tile{ .index = placed.tile.index, .column = placed.tile.column, .row = placed.tile.row, .rect = placed.rect };
        self.artifacts[index] = try buildWideTileArtifacts(
            self.allocator,
            component_tile,
            &.{region},
            coding.levels,
            scaffold_options,
            wideBlockStyle(coding),
        );
        self.initialized[index] = true;
    }
};

fn componentHasRoi(regions: []const RoiRegion, component: usize) bool {
    for (regions) |region| {
        if (region.component == null or region.component.? == component) return true;
    }
    return false;
}

/// Marks the coefficients of one tile-component (Mallat layout over `rect`)
/// that carry a ROI rectangle: in every band, the band coordinates of the
/// rectangle at that level, widened by three on each side to cover the 5/3
/// synthesis support (Annex H allows any mask; Maxshift needs none at the
/// decoder).
fn markWideRoiCoefficients(
    allocator: std.mem.Allocator,
    mask: []bool,
    rect: tile_grid.Rect,
    levels: u8,
    layout: native_samples.ComponentLayout,
    regions: []const RoiRegion,
    component: usize,
) !void {
    @memset(mask, false);
    const width: usize = rect.width();
    const bands = try subband.makeBandsForRegion(allocator, rect.x0, rect.y0, rect.x1, rect.y1, levels);
    defer allocator.free(bands);
    for (regions) |region| {
        if (region.component != null and region.component.? != component) continue;
        // The rectangle on the component grid.
        const x0: i64 = ceilDivU32(region.x0, layout.x_step);
        const y0: i64 = ceilDivU32(region.y0, layout.y_step);
        const x1: i64 = ceilDivU32(region.x1, layout.x_step);
        const y1: i64 = ceilDivU32(region.y1, layout.y_step);
        for (bands) |band| {
            const scale: i64 = @as(i64, 1) << @intCast(band.level);
            const low_x = @divFloor(x0, scale) - 3;
            const high_x = std.math.divCeil(i64, x1, scale) catch unreachable;
            const low_y = @divFloor(y0, scale) - 3;
            const high_y = std.math.divCeil(i64, y1, scale) catch unreachable;
            for (0..band.rect.height) |row| {
                const v: i64 = @as(i64, band.origin_y) + @as(i64, @intCast(row));
                if (v < low_y or v >= high_y + 3) continue;
                for (0..band.rect.width) |column| {
                    const u: i64 = @as(i64, band.origin_x) + @as(i64, @intCast(column));
                    if (u < low_x or u >= high_x + 3) continue;
                    mask[(band.rect.y + row) * width + band.rect.x + column] = true;
                }
            }
        }
    }
}

/// Runs `jobs` over `count` indices on their workers and returns the first
/// error any of them met.
fn runWideComponentJobs(jobs: []WideComponentTileJob, next_job: *std.atomic.Value(usize), count: usize, threads: []std.Thread) !void {
    next_job.store(0, .monotonic);
    var spawned: usize = 0;
    while (spawned + 1 < jobs.len) : (spawned += 1) {
        threads[spawned] = std.Thread.spawn(.{}, WideComponentTileJob.run, .{&jobs[spawned]}) catch |err| {
            next_job.store(count, .release);
            for (threads[0..spawned]) |thread| thread.join();
            return err;
        };
    }
    jobs[jobs.len - 1].run();
    for (threads[0..spawned]) |thread| thread.join();
    for (jobs) |job| try job.result;
}

/// SIZ, COD, QCD, QCC, and CRG of the componentwise path.
fn wideComponentwiseMainHeaderBytes(
    allocator: std.mem.Allocator,
    source: NativeSamplePlanes,
    quantizations: []const WideReversibleQuantization,
    levels: u8,
    encode_options: LosslessOptions,
    component_options: []const LosslessOptions,
    roi_shifts: []const u8,
) ![]u8 {
    const component_count = source.planes.len;
    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(allocator);

    // SIZ (A.5.1) with every component's precision, signedness, and sampling.
    const lsiz = std.math.add(usize, 38, try std.math.mul(usize, 3, component_count)) catch
        return CodestreamError.UnsupportedPayload;
    if (lsiz > std.math.maxInt(u16)) return CodestreamError.UnsupportedPayload;
    try appendMarker(allocator, &out, .siz);
    try appendU16Be(allocator, &out, @intCast(lsiz));
    try appendU16Be(allocator, &out, 0);
    try appendU32Be(allocator, &out, source.reference_x1);
    try appendU32Be(allocator, &out, source.reference_y1);
    try appendU32Be(allocator, &out, source.reference_x0);
    try appendU32Be(allocator, &out, source.reference_y0);
    try appendU32Be(allocator, &out, encode_options.tile_width);
    try appendU32Be(allocator, &out, encode_options.tile_height);
    try appendU32Be(allocator, &out, encode_options.tile_origin_x);
    try appendU32Be(allocator, &out, encode_options.tile_origin_y);
    try appendU16Be(allocator, &out, @intCast(component_count));
    for (source.planes) |plane| {
        const layout = plane.layout;
        const signed_flag: u8 = if (layout.signed) 0x80 else 0;
        try out.append(allocator, (layout.precision - 1) | signed_flag);
        try out.append(allocator, layout.x_step);
        try out.append(allocator, layout.y_step);
    }

    const two_byte_selector = component_count > 256;
    try appendCod(allocator, &out, levels, encode_options);
    for (component_options, 0..) |coding, component| {
        if (wideCodingMatchesCod(coding, encode_options, levels)) continue;
        try appendCocForComponent(allocator, &out, @intCast(component), two_byte_selector, coding);
    }
    // QCD serves every component with component 0's precision and COD's
    // levels; any other component gets a QCC with its own band count.
    try appendQcdWideReversible(allocator, &out, levels, quantizations[0]);
    for (quantizations, component_options, 0..) |quantization, coding, component| {
        if (std.meta.eql(quantization, quantizations[0]) and coding.levels == levels) continue;
        try appendQccWideReversible(allocator, &out, coding.levels, @intCast(component), two_byte_selector, quantization);
    }
    // RGN (A.6.3) with the Maxshift style and each ROI component's upshift.
    for (roi_shifts, 0..) |shift, component| {
        if (shift == 0) continue;
        const selector_bytes: u16 = if (two_byte_selector) 2 else 1;
        try appendMarker(allocator, &out, .rgn);
        try appendU16Be(allocator, &out, 2 + selector_bytes + 2);
        if (two_byte_selector) {
            try appendU16Be(allocator, &out, @intCast(component));
        } else {
            try out.append(allocator, @intCast(component));
        }
        try out.append(allocator, 0);
        try out.append(allocator, shift);
    }

    // CRG (A.9.1) when any component carries a registration offset.
    for (source.planes) |plane| {
        if (plane.layout.registration_x == 0 and plane.layout.registration_y == 0) continue;
        const lcrg = 2 + 4 * component_count;
        if (lcrg > std.math.maxInt(u16)) return CodestreamError.UnsupportedPayload;
        try appendMarker(allocator, &out, .crg);
        try appendU16Be(allocator, &out, @intCast(lcrg));
        for (source.planes) |registered| {
            try appendU16Be(allocator, &out, registered.layout.registration_x);
            try appendU16Be(allocator, &out, registered.layout.registration_y);
        }
        break;
    }
    return out.toOwnedSlice(allocator);
}

/// QCC (A.6.5) with the wide reversible signalling of one component; the
/// selector takes two bytes when the codestream has more than 256 components.
fn appendQccWideReversible(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    levels: u8,
    component: u16,
    two_byte_selector: bool,
    quantization: WideReversibleQuantization,
) !void {
    const bands = 1 + 3 * @as(u16, levels);
    const selector_bytes: u16 = if (two_byte_selector) 2 else 1;
    try appendMarker(allocator, out, .qcc);
    try appendU16Be(allocator, out, 3 + selector_bytes + bands);
    if (two_byte_selector) {
        try appendU16Be(allocator, out, component);
    } else {
        try out.append(allocator, @intCast(component));
    }
    try out.append(allocator, (quantization.guard_bits << 5) | @backingInt(QuantizationStyle.none));
    try out.append(allocator, quantization.exponent(.ll) << 3);
    for (0..levels) |_| {
        inline for (.{ subband.Kind.hl, subband.Kind.lh, subband.Kind.hh }) |kind| {
            try out.append(allocator, quantization.exponent(kind) << 3);
        }
    }
}

/// Forward RCT (ISO/IEC 15444-1 G.2.1) over three level-shifted planes, in
/// place from R/G/B to Y/Db/Dr.
fn forwardRctWide(planes: []const []i64) void {
    for (planes[0], planes[1], planes[2]) |*red, *green, *blue| {
        const y = @divFloor(red.* + 2 * green.* + blue.*, 4);
        const blue_difference = blue.* - green.*;
        const red_difference = red.* - green.*;
        red.* = y;
        green.* = blue_difference;
        blue.* = red_difference;
    }
}

fn wideBlockStyle(encode_options: LosslessOptions) ebcot.CodeBlockStyle {
    return .{
        .bypass = encode_options.bypass,
        .reset_context = encode_options.reset_context,
        .terminate_all = encode_options.terminate_all,
        .vertical_causal = encode_options.vertical_causal,
        .predictable_termination = encode_options.predictable_termination,
        .segmentation_symbols = encode_options.segmentation_symbols,
    };
}

fn wideScaffoldOptions(
    encode_options: LosslessOptions,
    precincts: *[33]packet_plan.Precinct,
    component_count: usize,
    precision: u8,
    quantization: WideReversibleQuantization,
    packet_order: tile_pipeline.PacketOrder,
) tile_pipeline.PacketScaffoldOptions {
    for (encode_options.precincts[0..encode_options.precinct_count], 0..) |precinct, index| {
        precincts[index] = .{ .width = precinct.width, .height = precinct.height };
    }
    var depths: [color.max_components]u8 = @splat(0);
    for (depths[0..component_count]) |*depth| depth.* = precision;
    return .{
        .layers = encode_options.layers,
        .block_width = encode_options.block_width,
        .block_height = encode_options.block_height,
        .precincts = precincts[0..encode_options.precinct_count],
        .packet_order = packet_order,
        .components = @intCast(component_count),
        .component_bit_depths = depths,
        .nominal_bitplanes = quantization.table(),
        .rates = encode_options.rates,
        .rate_count = encode_options.rate_count,
    };
}

/// One tile's packet artifacts from its transformed i64 planes. A coefficient
/// needing more than the 37 bitplanes Part 1 can signal refuses the image.
fn buildWideTileArtifacts(
    allocator: std.mem.Allocator,
    tile: tile_grid.Tile,
    planes: []const []const i64,
    levels: u8,
    scaffold_options: tile_pipeline.PacketScaffoldOptions,
    block_style: ebcot.CodeBlockStyle,
) !tile_pipeline.TileRpclEncodeArtifacts {
    return tile_pipeline.buildWideTileRpclEncodeArtifacts(
        allocator,
        tile,
        tile.rect.width(),
        tile.rect.height(),
        planes,
        levels,
        scaffold_options,
        block_style,
    ) catch |err| switch (err) {
        tile_pipeline.PacketScaffoldError.InvalidLayer => return CodestreamError.UnsupportedPayload,
        else => return err,
    };
}

/// The wide encoder's multi-tile path: each tile is cut from the level-shifted
/// (and RCT-transformed) planes, given its own origin-aware i64 5/3 and T1,
/// and the tiles are written by `assembleMultiTileArtifactsCodestream`. Tiles
/// are built on `options.threads` workers.
fn encodeNativeWideMultiTile(
    allocator: std.mem.Allocator,
    planes: []const []const i64,
    grid: tile_grid.Grid,
    levels: u8,
    quantization: WideReversibleQuantization,
    main_header: MultiTileMainHeader,
    options: LosslessOptions,
) ![]u8 {
    const total_start = monotonicNs();
    const components: u16 = @intCast(planes.len);
    try validateMultiTileCodingPath(options, components);
    const encode_options = normalizedEncodePrecinctOptions(options, levels);
    try validateMultiTileGeometry(grid, levels);

    const packet_order: tile_pipeline.PacketOrder = if (encode_options.poc_records.len != 0)
        .rpcl
    else switch (encode_options.progression) {
        .rpcl => .rpcl,
        .lrcp => .lrcp,
        .rlcp => .rlcp,
        .pcrl => .pcrl,
        .cprl => .cprl,
    };
    var scaffold_precincts: [33]packet_plan.Precinct = undefined;
    const tile_count = std.math.cast(usize, grid.tileCount()) orelse return CodestreamError.ImageTooLarge;
    const tiles = try allocator.alloc(tile_pipeline.TileRpclEncodeArtifacts, tile_count);
    var tiles_moved = false;
    errdefer if (!tiles_moved) allocator.free(tiles);
    const initialized = try allocator.alloc(bool, tile_count);
    defer allocator.free(initialized);
    @memset(initialized, false);
    errdefer if (!tiles_moved) {
        for (tiles, initialized) |*tile, is_initialized| {
            if (is_initialized) tile.deinit();
        }
    };

    var next_tile = std.atomic.Value(usize).init(0);
    const worker_count = @max(@as(usize, 1), @min(@as(usize, options.threads), tile_count));
    const jobs = try allocator.alloc(WideTileEncodeJob, worker_count);
    defer allocator.free(jobs);
    for (jobs) |*job| {
        job.* = .{
            .allocator = allocator,
            .planes = planes,
            .image_width = grid.params.xsiz,
            .grid = grid,
            .levels = levels,
            .scaffold_options = blk: {
                var scaffold = wideScaffoldOptions(encode_options, &scaffold_precincts, planes.len, main_header.bit_depth, quantization, packet_order);
                // Threads the tile workers leave over code blocks inside a tile.
                scaffold.threads = @intCast(@max(1, @as(usize, options.threads) / worker_count));
                break :blk scaffold;
            },
            .block_style = wideBlockStyle(encode_options),
            .tiles = tiles,
            .initialized = initialized,
            .next_tile = &next_tile,
        };
    }
    const threads = try allocator.alloc(std.Thread, worker_count - 1);
    defer allocator.free(threads);
    var spawned: usize = 0;
    while (spawned < threads.len) : (spawned += 1) {
        threads[spawned] = std.Thread.spawn(.{}, WideTileEncodeJob.run, .{&jobs[spawned]}) catch |err| {
            next_tile.store(tile_count, .release);
            for (threads[0..spawned]) |thread| thread.join();
            return err;
        };
    }
    jobs[worker_count - 1].run();
    for (threads[0..spawned]) |thread| thread.join();
    for (jobs) |job| try job.result;
    for (initialized) |is_initialized| {
        if (!is_initialized) return CodestreamError.InvalidCodestream;
    }
    // Rate targets: one slope threshold over every block of every tile.
    try tile_pipeline.applyGridPcrdTargets(allocator, tiles, jobs[0].scaffold_options);

    var artifacts = tile_pipeline.TileRpclEncodeGridArtifacts{
        .allocator = allocator,
        .grid = grid,
        .tiles = tiles,
    };
    tiles_moved = true;
    defer artifacts.deinit();
    return assembleMultiTileArtifactsCodestream(
        allocator,
        artifacts,
        main_header,
        components,
        levels,
        encode_options,
        null,
        total_start,
    );
}

const WideTileEncodeJob = struct {
    allocator: std.mem.Allocator,
    planes: []const []const i64,
    image_width: usize,
    grid: tile_grid.Grid,
    levels: u8,
    scaffold_options: tile_pipeline.PacketScaffoldOptions,
    block_style: ebcot.CodeBlockStyle,
    tiles: []tile_pipeline.TileRpclEncodeArtifacts,
    initialized: []bool,
    next_tile: *std.atomic.Value(usize),
    result: anyerror!void = {},

    fn run(self: *WideTileEncodeJob) void {
        while (true) {
            const index = self.next_tile.fetchAdd(1, .monotonic);
            if (index >= self.tiles.len) return;
            self.tiles[index] = self.buildTile(index) catch |err| {
                self.result = err;
                // Stop the other workers at their next tile.
                self.next_tile.store(self.tiles.len, .monotonic);
                return;
            };
            self.initialized[index] = true;
        }
    }

    fn buildTile(self: *WideTileEncodeJob, index: usize) !tile_pipeline.TileRpclEncodeArtifacts {
        const allocator = self.allocator;
        const tile = try self.grid.tile(@intCast(index));
        const tile_width: usize = tile.rect.width();
        const tile_height: usize = tile.rect.height();
        const tile_planes = try allocator.alloc([]i64, self.planes.len);
        var built: usize = 0;
        defer {
            for (tile_planes[0..built]) |plane| allocator.free(plane);
            allocator.free(tile_planes);
        }
        for (self.planes) |plane| {
            const region = try allocator.alloc(i64, tile_width * tile_height);
            tile_planes[built] = region;
            built += 1;
            for (0..tile_height) |row| {
                const start = (@as(usize, tile.rect.y0) + row) * self.image_width + tile.rect.x0;
                @memcpy(region[row * tile_width ..][0..tile_width], plane[start..][0..tile_width]);
            }
            const achieved = try wavelet_int.forward53WideOriginThreaded(allocator, region, tile_width, tile_height, self.levels, tile.rect.x0, tile.rect.y0, self.scaffold_options.threads);
            if (achieved != self.levels) return CodestreamError.InvalidCodestream;
        }
        return buildWideTileArtifacts(allocator, tile, tile_planes, self.levels, self.scaffold_options, self.block_style);
    }
};

/// Multi-tile planar encode: grayscale, gray+alpha, and RGBA (with RCT over
/// the colour planes or without MCT) through the same tile pipeline, tile-part
/// divisions, global PCRD, POC, and packed-header options as multi-tile RGB.
/// Each tile's planes are cut from `planar` and transformed by
/// `tile_pipeline.forwardPlanarTile`.
fn encodeLosslessPlanarMultiTile(
    allocator: std.mem.Allocator,
    planar: color.SamplePlanes,
    grid: tile_grid.Grid,
    options: LosslessOptions,
    mixed_component_precision: bool,
) ![]u8 {
    const total_start = monotonicNs();
    // One QCD serves every component on this path.
    if (mixed_component_precision) return CodestreamError.UnsupportedPayload;
    const components: u16 = @intCast(planar.planes.len);
    const reversible = options.transform == .reversible_5_3 and options.quantization == .none;
    const irreversible = options.transform == .irreversible_9_7 and
        (options.quantization == .scalar_expounded or options.quantization == .scalar_derived);
    if (!reversible and !irreversible) return CodestreamError.UnsupportedPayload;
    // RGBA may transform its colour planes: RCT with 5/3, ICT with 9/7.
    const rct_alpha = reversible and options.mct == .rct and components == 4;
    const ict_alpha = irreversible and options.mct == .ict and components == 4;
    if (options.mct != .none and !rct_alpha and !ict_alpha) return CodestreamError.UnsupportedPayload;
    try validateLosslessRequest(grid, options);

    var context = PlanarTileFrontEndContext{
        .planar = planar,
        .rct_alpha = rct_alpha,
        .irreversible = irreversible,
        .ict_alpha = ict_alpha,
        .quantization = options.quantization,
    };
    // The tile pipeline checks the grid against these dimensions; the samples
    // come from the front end's own planes.
    const dimensions = image.RgbImage{
        .allocator = allocator,
        .width = planar.width,
        .height = planar.height,
        .bit_depth = planar.bit_depth,
        .samples = &.{},
    };
    return encodeLosslessMultiTileMeasured(
        allocator,
        dimensions,
        grid,
        options,
        components,
        .{ .context = @ptrCast(&context), .build = buildPlanarTransformedTile },
        null,
        total_start,
    );
}

const PlanarTileFrontEndContext = struct {
    planar: color.SamplePlanes,
    rct_alpha: bool,
    irreversible: bool = false,
    ict_alpha: bool = false,
    quantization: QuantizationStyle = .none,
};

fn buildPlanarTransformedTile(
    context: *const anyopaque,
    allocator: std.mem.Allocator,
    source: image.RgbImage,
    tile: tile_grid.Tile,
    levels: u8,
) anyerror!tile_pipeline.RctTile {
    _ = source;
    const ctx: *const PlanarTileFrontEndContext = @ptrCast(@alignCast(context));
    var tile_planes = try extractPlanarTile(allocator, ctx.planar, tile.rect);
    defer tile_planes.deinit();
    if (ctx.irreversible) {
        const planes = try forwardIrreversiblePlanarRegion(
            allocator,
            tile_planes,
            levels,
            ctx.quantization,
            ctx.ict_alpha,
            tile.rect.x0,
            tile.rect.y0,
        );
        return .{ .tile = tile, .planes = planes };
    }
    return tile_pipeline.forwardPlanarTile(allocator, tile_planes, tile, levels, ctx.rct_alpha);
}

/// Irreversible planar front end for one region: the DC level shift into
/// floats (with ICT over the colour planes of RGBA when `ict` is set, the
/// alpha plane left independent), then each plane's origin-aware 9/7 DWT and
/// deadzone quantization, exactly as the RGB front end does per plane.
fn forwardIrreversiblePlanarRegion(
    allocator: std.mem.Allocator,
    planar: color.SamplePlanes,
    levels: u8,
    quantization: QuantizationStyle,
    ict: bool,
    x0: u32,
    y0: u32,
) !color.RctPlanes {
    const count = planar.planes.len;
    if (count == 0 or count > color.max_components) return CodestreamError.UnsupportedPayload;
    if (ict and count != 4) return CodestreamError.UnsupportedPayload;
    const bit_depth = planar.bit_depth;
    if (bit_depth == 0 or bit_depth > 16) return CodestreamError.UnsupportedPayload;
    const pixels = try std.math.mul(usize, planar.width, planar.height);
    const shift: f32 = @floatFromInt(@as(i32, 1) << @as(u5, @intCast(bit_depth - 1)));

    var floats: [color.max_components][]f32 = undefined;
    var allocated: usize = 0;
    defer for (floats[0..allocated]) |plane| allocator.free(plane);
    while (allocated < count) : (allocated += 1) {
        floats[allocated] = try allocator.alloc(f32, pixels);
        for (planar.planes[allocated], floats[allocated]) |sample, *value| {
            value.* = @as(f32, @floatFromInt(sample)) - shift;
        }
    }
    if (ict) {
        // Reuse the RGB ICT so the colour planes match the RGB front end
        // bit for bit.
        const interleaved = try allocator.alloc(u16, pixels * 3);
        defer allocator.free(interleaved);
        for (0..pixels) |pixel| {
            for (0..3) |component| interleaved[pixel * 3 + component] = planar.planes[component][pixel];
        }
        var transformed = try color.forwardIct(allocator, .{
            .allocator = allocator,
            .width = planar.width,
            .height = planar.height,
            .bit_depth = bit_depth,
            .samples = interleaved,
        });
        defer transformed.deinit();
        for (0..3) |component| @memcpy(floats[component], transformed.planes[component]);
    }

    const width_u32 = std.math.cast(u32, planar.width) orelse return CodestreamError.ImageTooLarge;
    const height_u32 = std.math.cast(u32, planar.height) orelse return CodestreamError.ImageTooLarge;
    const x1 = std.math.add(u32, x0, width_u32) catch return CodestreamError.ImageTooLarge;
    const y1 = std.math.add(u32, y0, height_u32) catch return CodestreamError.ImageTooLarge;
    const bands = try subband.makeBandsForRegion(allocator, x0, y0, x1, y1, levels);
    defer allocator.free(bands);
    const deltas = try allocator.alloc(f64, bands.len);
    defer allocator.free(deltas);
    for (bands, deltas) |band, *delta| {
        delta.* = irreversibleBandDelta(
            bit_depth,
            band.kind,
            try irreversibleBandStepSizeFor(quantization, bit_depth, band.kind, band.level, levels),
        );
    }

    var out = try color.RctPlanes.init(allocator, planar.width, planar.height, bit_depth, count);
    errdefer out.deinit();
    var jobs: [color.max_components]IrreversibleForwardPlaneJob = undefined;
    for (0..count) |component| {
        jobs[component] = .{
            .plane = floats[component],
            .quantized = out.planes[component],
            .width = planar.width,
            .height = planar.height,
            .levels = levels,
            .x0 = x0,
            .y0 = y0,
            .bands = bands,
            .deltas = deltas,
        };
    }
    // Tiles already run on parallel tile workers; keep the planes serial.
    try runComponentJobs(IrreversibleForwardPlaneJob, allocator, jobs[0..count], 1, irreversibleForwardPlaneWorker);
    return out;
}

/// Copies one tile's window out of every uniformly sampled plane.
fn extractPlanarTile(
    allocator: std.mem.Allocator,
    planar: color.SamplePlanes,
    rect: tile_grid.Rect,
) !color.SamplePlanes {
    const width: usize = rect.width();
    const height: usize = rect.height();
    if (rect.x1 > planar.width or rect.y1 > planar.height) return CodestreamError.InvalidCodestream;
    var out = try color.SamplePlanes.init(allocator, width, height, planar.bit_depth, planar.planes.len);
    errdefer out.deinit();
    for (planar.planes, out.planes) |source, destination| {
        for (0..height) |row| {
            const start = (@as(usize, rect.y0) + row) * planar.width + rect.x0;
            @memcpy(destination[row * width ..][0..width], source[start..][0..width]);
        }
    }
    return out;
}

/// Per-component subsampling factors (SIZ XRsiz/YRsiz) for the sampled
/// planar encoder.
pub const ComponentSampling = struct {
    xrsiz: u8,
    yrsiz: u8,
};

/// F3b sampled reversible encode: 1..4 unsigned 8/16-bit component planes with
/// explicit per-component dimensions and XRsiz/YRsiz subsampling, no MCT,
/// single or multi-tile, reversible 5/3, ISO MQ, RPCL, one or more untargeted layers,
/// and inline PLT/PLT-less, PPT, or PPM packet headers. Each component is
/// encoded independently through the single-component scaffold at its own
/// dimensions; the per-component packet streams are then merged into the
/// default sampled RPCL order or a checked complete POC schedule. Everything
/// outside that envelope fails closed.
pub fn encodeLosslessSampledPlanarWithOptions(
    allocator: std.mem.Allocator,
    planar: color.SamplePlanes,
    sampling: []const ComponentSampling,
    options: LosslessOptions,
) ![]u8 {
    if (planar.width == 0 or planar.height == 0 or
        planar.width > std.math.maxInt(u32) or planar.height > std.math.maxInt(u32))
    {
        return CodestreamError.ImageTooLarge;
    }
    const component_count = planar.planes.len;
    if (component_count == 0 or component_count > color.max_components) {
        return CodestreamError.UnsupportedPayload;
    }
    if (sampling.len != component_count) return CodestreamError.InvalidCodestream;

    // Current envelope: reversible 5/3, no MCT, RPCL, untargeted layers,
    // shared inline/PPT/PPM framing, and optional checked POC scheduling.
    if (options.transform != .reversible_5_3 or options.quantization != .none or
        options.mct != .none or options.progression != .rpcl or
        options.layers == 0 or options.layers > max_quality_layers or
        options.rate_count != 0 or
        options.emit_temporary_payload_sidecar or options.component_coding.len != 0 or options.roi_regions.len != 0 or
        options.t1_backend != .iso_mq or options.bypass or options.terminate_all or
        options.reset_context or options.vertical_causal or
        options.predictable_termination or options.segmentation_symbols)
    {
        return CodestreamError.UnsupportedPayload;
    }
    if (options.poc_in_tile_header and options.poc_records.len == 0) {
        return CodestreamError.InvalidCodestream;
    }
    if (options.ppm and options.ppt) return CodestreamError.UnsupportedPayload;
    // PPT tile-parts retain body-length PLT accounting. PPM owns packet-header
    // grouping in the main header and intentionally omits PLT.
    if (options.ppt and !options.plt) return CodestreamError.UnsupportedPayload;
    if (options.tile_part_divisions != null) return CodestreamError.UnsupportedPayload;
    if (options.levels > 32) return CodestreamError.TooManyLevels;

    const width_u32: u32 = @intCast(planar.width);
    const height_u32: u32 = @intCast(planar.height);
    const reference_x1 = std.math.add(u32, options.image_origin_x, width_u32) catch
        return CodestreamError.ImageTooLarge;
    const reference_y1 = std.math.add(u32, options.image_origin_y, height_u32) catch
        return CodestreamError.ImageTooLarge;
    const grid = tile_grid.Grid.init(.{
        .xsiz = reference_x1,
        .ysiz = reference_y1,
        .xosiz = options.image_origin_x,
        .yosiz = options.image_origin_y,
        .xtsiz = options.tile_width,
        .ytsiz = options.tile_height,
        .xtosiz = options.tile_origin_x,
        .ytosiz = options.tile_origin_y,
    }) catch return CodestreamError.InvalidCodestream;

    const reference_levels = actualDwtLevels(planar.width, planar.height, options.levels);

    var component_xrsiz: [max_codestream_components]u8 = @splat(1);
    var component_yrsiz: [max_codestream_components]u8 = @splat(1);
    var component_bit_depths: [max_codestream_components]u8 = @splat(0);
    var any_subsampled = false;
    for (0..component_count) |component| {
        const xrsiz = sampling[component].xrsiz;
        const yrsiz = sampling[component].yrsiz;
        if (xrsiz == 0 or yrsiz == 0) return CodestreamError.InvalidCodestream;
        const expected_width = ceilDivU32(reference_x1, xrsiz) - ceilDivU32(options.image_origin_x, xrsiz);
        const expected_height = ceilDivU32(reference_y1, yrsiz) - ceilDivU32(options.image_origin_y, yrsiz);
        const dims = planar.componentDimensions(component) orelse return CodestreamError.InvalidCodestream;
        if (dims[0] != expected_width or dims[1] != expected_height) {
            return CodestreamError.InvalidCodestream;
        }
        const depth = planar.componentBitDepth(component) orelse return CodestreamError.InvalidCodestream;
        if (depth != 8 and depth != 16) return CodestreamError.UnsupportedPayload;
        component_xrsiz[component] = xrsiz;
        component_yrsiz[component] = yrsiz;
        component_bit_depths[component] = depth;
        if (xrsiz != 1 or yrsiz != 1) any_subsampled = true;
    }
    // A single-tile all-1 sampling layout is just the planar profile, so it
    // stays there and this path keeps carrying genuine subsampling. A
    // multi-tile all-1 layout is still accepted here for existing callers,
    // although `encodeLosslessPlanarWithOptions` now encodes tile grids with
    // the full multi-tile option set.
    if (!any_subsampled and grid.isSingleTile()) return CodestreamError.UnsupportedPayload;

    const encode_options = normalizedEncodePrecinctOptions(options, reference_levels);
    var scaffold_precincts: [33]packet_plan.Precinct = undefined;
    for (encode_options.precincts[0..encode_options.precinct_count], 0..) |precinct, index| {
        scaffold_precincts[index] = .{ .width = precinct.width, .height = precinct.height };
    }
    const scaffold_options = tile_pipeline.PacketScaffoldOptions{
        .layers = encode_options.layers,
        .block_width = encode_options.block_width,
        .block_height = encode_options.block_height,
        .precincts = scaffold_precincts[0..encode_options.precinct_count],
    };
    const block_style = ebcot.CodeBlockStyle{};

    if (!grid.isSingleTile()) {
        if (planar.bit_depth != 8 and planar.bit_depth != 16) {
            return CodestreamError.UnsupportedPayload;
        }
        return assembleSampledMultiTileCodestream(
            allocator,
            planar,
            grid,
            component_bit_depths,
            component_xrsiz,
            component_yrsiz,
            reference_levels,
            scaffold_options,
            block_style,
            encode_options,
        );
    }

    var stream = try buildSampledTilePacketStream(
        allocator,
        planar,
        try grid.tile(0),
        component_bit_depths,
        component_xrsiz,
        component_yrsiz,
        options.image_origin_x,
        options.image_origin_y,
        reference_levels,
        scaffold_options,
        block_style,
        encode_options.layers,
        encode_options.poc_records,
    );
    defer stream.deinit();

    return assembleSampledSingleTileCodestream(allocator, .{
        .width = planar.width,
        .height = planar.height,
        .bit_depth = planar.bit_depth,
        .component_bit_depths = component_bit_depths,
        .component_xrsiz = component_xrsiz,
        .component_yrsiz = component_yrsiz,
        .components = @intCast(component_count),
        .levels = reference_levels,
        .packet_lengths = stream.packet_lengths,
        .packet_header_lengths = stream.packet_header_lengths,
        .packet_bytes = stream.packet_bytes,
    }, encode_options);
}

const SampledTilePacketStream = struct {
    allocator: std.mem.Allocator,
    tile: tile_grid.Tile,
    packet_lengths: []u32,
    packet_header_lengths: []u32,
    packet_bytes: []u8,
    /// The tile's packet sequence in stream order, when the merge kept it.
    sequence: []packet_plan.Packet = &.{},

    fn deinit(self: *SampledTilePacketStream) void {
        self.allocator.free(self.sequence);
        self.allocator.free(self.packet_bytes);
        self.allocator.free(self.packet_header_lengths);
        self.allocator.free(self.packet_lengths);
        self.* = undefined;
    }
};

fn buildSampledTilePacketStream(
    allocator: std.mem.Allocator,
    planar: color.SamplePlanes,
    reference_tile: tile_grid.Tile,
    component_bit_depths: [max_codestream_components]u8,
    component_xrsiz: [max_codestream_components]u8,
    component_yrsiz: [max_codestream_components]u8,
    reference_x0: u32,
    reference_y0: u32,
    reference_levels: u8,
    scaffold_options: tile_pipeline.PacketScaffoldOptions,
    block_style: ebcot.CodeBlockStyle,
    layer_count: u16,
    poc_records: []const poc.Record,
) !SampledTilePacketStream {
    const component_count = planar.planes.len;
    var per_component: [max_codestream_components]tile_pipeline.TileRpclEncodeArtifacts = undefined;
    var built: usize = 0;
    defer for (per_component[0..built]) |*artifact| artifact.deinit();

    var sampled_plans: [max_codestream_components]packet_plan.SampledComponentPlan = undefined;
    while (built < component_count) : (built += 1) {
        const full_dims = planar.componentDimensions(built) orelse return CodestreamError.InvalidCodestream;
        const xrsiz = component_xrsiz[built];
        const yrsiz = component_yrsiz[built];
        const component_x0 = ceilDivU32(reference_tile.rect.x0, xrsiz);
        const component_y0 = ceilDivU32(reference_tile.rect.y0, yrsiz);
        const component_x1 = ceilDivU32(reference_tile.rect.x1, xrsiz);
        const component_y1 = ceilDivU32(reference_tile.rect.y1, yrsiz);
        const image_component_x0 = ceilDivU32(reference_x0, xrsiz);
        const image_component_y0 = ceilDivU32(reference_y0, yrsiz);
        if (component_x1 <= component_x0 or component_y1 <= component_y0) {
            return CodestreamError.UnsupportedPayload;
        }
        if (component_x0 < image_component_x0 or component_y0 < image_component_y0) {
            return CodestreamError.InvalidCodestream;
        }
        const tile_width: usize = component_x1 - component_x0;
        const tile_height: usize = component_y1 - component_y0;
        if (component_x1 - image_component_x0 > full_dims[0] or
            component_y1 - image_component_y0 > full_dims[1])
        {
            return CodestreamError.InvalidCodestream;
        }

        const depth = component_bit_depths[built];
        var component_tile_planes = try color.SamplePlanes.initWithComponentLayouts(
            allocator,
            tile_width,
            tile_height,
            &.{depth},
            &.{tile_width},
            &.{tile_height},
        );
        defer component_tile_planes.deinit();
        for (0..tile_height) |row| {
            const source_x = component_x0 - image_component_x0;
            const source_y = component_y0 - image_component_y0;
            const source_start = (@as(usize, source_y) + row) * full_dims[0] + source_x;
            const destination_start = row * tile_width;
            @memcpy(
                component_tile_planes.planes[0][destination_start..][0..tile_width],
                planar.planes[built][source_start..][0..tile_width],
            );
        }

        const component_tile = tile_grid.Tile{
            .index = reference_tile.index,
            .column = reference_tile.column,
            .row = reference_tile.row,
            .rect = .{
                .x0 = component_x0,
                .y0 = component_y0,
                .x1 = component_x1,
                .y1 = component_y1,
            },
        };
        per_component[built] = try tile_pipeline.buildPlanarTileRpclEncodeArtifactsIsoMq(
            allocator,
            component_tile_planes,
            component_tile,
            reference_levels,
            scaffold_options,
            block_style,
        );
        if (per_component[built].levels != reference_levels or
            per_component[built].scaffold.components != 1)
        {
            return CodestreamError.UnsupportedPayload;
        }
        sampled_plans[built] = .{
            .plan = per_component[built].scaffold.plan,
            .xrsiz = xrsiz,
            .yrsiz = yrsiz,
        };
    }

    return mergeSampledComponentPacketStreams(
        allocator,
        reference_tile,
        per_component[0..component_count],
        sampled_plans[0..component_count],
        layer_count,
        poc_records,
    );
}

/// Merges one tile's single-component packet streams (each in its own RPCL
/// order) into the tile's sampled progression: the canonical sampled RPCL
/// sequence, or the sequence composed from `poc_records`.
fn mergeSampledComponentPacketStreams(
    allocator: std.mem.Allocator,
    reference_tile: tile_grid.Tile,
    per_component: []const tile_pipeline.TileRpclEncodeArtifacts,
    sampled_plans: []const packet_plan.SampledComponentPlan,
    layer_count: u16,
    poc_records: []const poc.Record,
) !SampledTilePacketStream {
    const component_count = per_component.len;
    if (sampled_plans.len != component_count) return CodestreamError.InvalidCodestream;
    const global = try buildSampledPocPacketSequence(
        allocator,
        sampled_plans,
        layer_count,
        reference_tile.rect.x0,
        reference_tile.rect.y0,
        poc_records,
    );
    errdefer allocator.free(global);

    const layers: u64 = layer_count;
    const resolution_offsets = try allocator.alloc([33]u64, component_count);
    defer allocator.free(resolution_offsets);
    for (0..component_count) |component| {
        const plan = per_component[component].scaffold.plan;
        var running: u64 = 0;
        for (0..plan.resolution_count) |resolution| {
            resolution_offsets[component][resolution] = running;
            running += plan.resolutions[resolution].packets;
        }
    }

    var merged_bytes: std.ArrayList(u8) = .empty;
    errdefer merged_bytes.deinit(allocator);
    var merged_lengths: std.ArrayList(u32) = .empty;
    errdefer merged_lengths.deinit(allocator);
    var merged_header_lengths: std.ArrayList(u32) = .empty;
    errdefer merged_header_lengths.deinit(allocator);
    try merged_lengths.ensureTotalCapacity(allocator, global.len);
    try merged_header_lengths.ensureTotalCapacity(allocator, global.len);

    for (global) |packet| {
        const component = packet.component;
        if (component >= component_count) return CodestreamError.InvalidCodestream;
        const stream = per_component[component].stream;
        const local_position = try std.math.add(
            u64,
            try std.math.mul(u64, packet.precinct_index, layers),
            packet.layer,
        );
        const local = try std.math.add(
            u64,
            resolution_offsets[component][packet.resolution],
            local_position,
        );
        const local_index = std.math.cast(usize, local) orelse return CodestreamError.InvalidCodestream;
        if (local_index >= stream.packet_lengths.len) return CodestreamError.InvalidCodestream;
        const length = stream.packet_lengths[local_index];
        const offset = try rpclPacketByteOffset(stream.packet_lengths, local_index);
        try merged_lengths.append(allocator, length);
        try merged_header_lengths.append(allocator, stream.packet_header_lengths[local_index]);
        try merged_bytes.appendSlice(allocator, stream.bytes[offset..][0..length]);
    }

    const packet_lengths = try merged_lengths.toOwnedSlice(allocator);
    errdefer allocator.free(packet_lengths);
    const packet_header_lengths = try merged_header_lengths.toOwnedSlice(allocator);
    errdefer allocator.free(packet_header_lengths);
    const packet_bytes = try merged_bytes.toOwnedSlice(allocator);
    return .{
        .allocator = allocator,
        .tile = reference_tile,
        .packet_lengths = packet_lengths,
        .packet_header_lengths = packet_header_lengths,
        .packet_bytes = packet_bytes,
        .sequence = global,
    };
}

const SampledAssemblyInput = struct {
    width: usize,
    height: usize,
    bit_depth: u8,
    component_bit_depths: [max_codestream_components]u8,
    component_xrsiz: [max_codestream_components]u8,
    component_yrsiz: [max_codestream_components]u8,
    components: u16,
    levels: u8,
    packet_lengths: []const u32,
    packet_header_lengths: []const u32,
    packet_bytes: []const u8,
};

fn assembleSampledMultiTileCodestream(
    allocator: std.mem.Allocator,
    planar: color.SamplePlanes,
    grid: tile_grid.Grid,
    component_bit_depths: [max_codestream_components]u8,
    component_xrsiz: [max_codestream_components]u8,
    component_yrsiz: [max_codestream_components]u8,
    levels: u8,
    scaffold_options: tile_pipeline.PacketScaffoldOptions,
    block_style: ebcot.CodeBlockStyle,
    encode_options: LosslessOptions,
) ![]u8 {
    const tile_count = std.math.cast(usize, grid.tileCount()) orelse return CodestreamError.ImageTooLarge;
    if (tile_count == 0 or tile_count > std.math.maxInt(u16)) return CodestreamError.UnsupportedPayload;
    const streams = try allocator.alloc(SampledTilePacketStream, tile_count);
    defer allocator.free(streams);
    var initialized: usize = 0;
    defer for (streams[0..initialized]) |*stream| stream.deinit();

    var iterator = grid.iterator();
    while (try iterator.next()) |tile| {
        if (initialized >= streams.len) return CodestreamError.InvalidCodestream;
        streams[initialized] = try buildSampledTilePacketStream(
            allocator,
            planar,
            tile,
            component_bit_depths,
            component_xrsiz,
            component_yrsiz,
            grid.params.xosiz,
            grid.params.yosiz,
            levels,
            scaffold_options,
            block_style,
            encode_options.layers,
            encode_options.poc_records,
        );
        initialized += 1;
    }
    if (initialized != streams.len) return CodestreamError.InvalidCodestream;

    const main_header = try sampledMainHeaderBytes(allocator, .{
        .width = @intCast(planar.width),
        .height = @intCast(planar.height),
        .bit_depth = planar.bit_depth,
        .component_bit_depths = component_bit_depths,
        .component_xrsiz = component_xrsiz,
        .component_yrsiz = component_yrsiz,
        .components = @intCast(planar.planes.len),
        .image_origin_x = encode_options.image_origin_x,
        .image_origin_y = encode_options.image_origin_y,
        .tile_width = encode_options.tile_width,
        .tile_height = encode_options.tile_height,
        .tile_origin_x = encode_options.tile_origin_x,
        .tile_origin_y = encode_options.tile_origin_y,
    }, levels, planar.bit_depth, encode_options);
    defer allocator.free(main_header);
    return writeSampledMultiTileCodestream(allocator, streams, main_header, @intCast(planar.planes.len), levels, encode_options);
}

/// SIZ, COD, and QCD of the sampled planar encoder.
fn sampledMainHeaderBytes(
    allocator: std.mem.Allocator,
    profile: SizProfile,
    levels: u8,
    bit_depth: u8,
    encode_options: LosslessOptions,
) ![]u8 {
    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(allocator);
    try appendSizForComponents(allocator, &out, profile);
    try appendCod(allocator, &out, levels, encode_options);
    try appendQcd(allocator, &out, levels, bit_depth, encode_options);
    return out.toOwnedSlice(allocator);
}

/// Writes one tile-part per tile from merged per-tile packet streams after a
/// prebuilt main header (SIZ through QCD/QCC): POC, TLM, PPM, then each tile
/// with its POC, PLT or PPT, and packets.
fn writeSampledMultiTileCodestream(
    allocator: std.mem.Allocator,
    streams: []const SampledTilePacketStream,
    main_header: []const u8,
    components: u16,
    levels: u8,
    encode_options: LosslessOptions,
) ![]u8 {
    return writeSampledTilePartsCodestream(allocator, streams, null, main_header, components, levels, encode_options);
}

/// The sampled writers' tile-part layout: each tile split into consecutive
/// runs of its packet sequence (`tile_runs[t]` holds the packet counts of
/// tile t's parts), or one part per tile when `tile_runs` is null. Parts are
/// written tile by tile; a tile's POC goes in its first part, and its SOP
/// numbering and PPT `Zppt` indices run on across its parts. TLM and PPM
/// carry one entry or group per tile-part.
fn writeSampledTilePartsCodestream(
    allocator: std.mem.Allocator,
    streams: []const SampledTilePacketStream,
    tile_runs: ?[]const []const usize,
    main_header: []const u8,
    components: u16,
    levels: u8,
    encode_options: LosslessOptions,
) ![]u8 {
    if (tile_runs) |runs| {
        if (runs.len != streams.len) return CodestreamError.InvalidCodestream;
    }
    var part_count: usize = 0;
    for (streams, 0..) |stream, tile| {
        const count = if (tile_runs) |runs| runs[tile].len else 1;
        if (count == 0 or count > std.math.maxInt(u8)) return CodestreamError.UnsupportedPayload;
        if (stream.tile.index > std.math.maxInt(u16)) return CodestreamError.UnsupportedPayload;
        part_count += count;
    }
    const parts = try allocator.alloc(MultiTilePacketPart, part_count);
    defer allocator.free(parts);
    const uses_packed_headers = encode_options.ppm or encode_options.ppt;
    const tile_poc_bytes = if (encode_options.poc_in_tile_header)
        try pocMarkerByteCount(encode_options)
    else
        0;
    var part_index: usize = 0;
    for (streams, 0..) |stream, tile| {
        const whole = [_]usize{stream.packet_lengths.len};
        const runs: []const usize = if (tile_runs) |all| all[tile] else &whole;
        var first: usize = 0;
        for (runs, 0..) |count, run| {
            if (first + count > stream.packet_lengths.len) return CodestreamError.InvalidCodestream;
            const lengths = stream.packet_lengths[first..][0..count];
            const header_lengths = stream.packet_header_lengths[first..][0..count];
            const framed_bytes = if (uses_packed_headers)
                try packedPacketBodyByteCount(encode_options, lengths, header_lengths)
            else
                try rpclPacketPayloadByteCount(encode_options, lengths);
            const plt_bytes = if (encode_options.ppm or !encode_options.plt)
                0
            else if (uses_packed_headers)
                try pltBytesForPackedPacketLengths(encode_options, lengths, header_lengths)
            else
                try pltBytesForRpclPacketLengths(encode_options, lengths);
            const ppt_bytes = if (encode_options.ppt)
                try pptMarkerByteCount(encode_options, header_lengths)
            else
                0;
            const poc_bytes = if (run == 0) tile_poc_bytes else 0;
            const psot = std.math.cast(
                u32,
                try std.math.add(
                    usize,
                    14,
                    try std.math.add(
                        usize,
                        framed_bytes,
                        try std.math.add(usize, plt_bytes, try std.math.add(usize, ppt_bytes, poc_bytes)),
                    ),
                ),
            ) orelse return CodestreamError.ImageTooLarge;
            parts[part_index] = .{
                .tile_index = @intCast(stream.tile.index),
                .tile_part_index = @intCast(run),
                .tile_part_count = @intCast(runs.len),
                .first_packet = first,
                .packet_count = count,
                .psot = psot,
            };
            part_index += 1;
            first += count;
        }
        if (first != stream.packet_lengths.len) return CodestreamError.InvalidCodestream;
    }

    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(allocator);
    try appendMarker(allocator, &out, .soc);
    try out.appendSlice(allocator, main_header);
    if (encode_options.poc_records.len != 0 and !encode_options.poc_in_tile_header) {
        try appendPocForComponents(allocator, &out, levels, components, encode_options);
    }
    if (encode_options.tlm) try appendMultiTileTlm(allocator, &out, parts);

    var ppm_groups: [][]u8 = &.{};
    var ppm_group_count: usize = 0;
    defer {
        for (ppm_groups[0..ppm_group_count]) |group| allocator.free(group);
        if (ppm_groups.len != 0) allocator.free(ppm_groups);
    }
    if (encode_options.ppm) {
        ppm_groups = try allocator.alloc([]u8, parts.len);
        var tile_cursor: usize = 0;
        for (parts) |part| {
            while (streams[tile_cursor].tile.index != part.tile_index) tile_cursor += 1;
            const stream = streams[tile_cursor];
            const bytes = try sampledPartPacketBytes(stream, part);
            ppm_groups[ppm_group_count] = try collectPackedPacketHeaders(
                allocator,
                encode_options,
                stream.packet_lengths[part.first_packet..][0..part.packet_count],
                stream.packet_header_lengths[part.first_packet..][0..part.packet_count],
                bytes,
            );
            ppm_group_count += 1;
        }
        try appendPpmPacketHeaderGroups(allocator, &out, ppm_groups);
    }

    var cursor: usize = 0;
    for (streams) |stream| {
        var packet_sequence: u16 = 0;
        var ppt_marker_index: u16 = 0;
        const tile_parts = parts[cursor..][0..parts[cursor].tile_part_count];
        cursor += tile_parts.len;
        for (tile_parts) |part| {
            const lengths = stream.packet_lengths[part.first_packet..][0..part.packet_count];
            const header_lengths = stream.packet_header_lengths[part.first_packet..][0..part.packet_count];
            const bytes = try sampledPartPacketBytes(stream, part);
            try appendSot(allocator, &out, part.tile_index, part.psot, part.tile_part_index, part.tile_part_count);
            if (encode_options.poc_in_tile_header and part.tile_part_index == 0) {
                try appendPocForComponents(allocator, &out, levels, components, encode_options);
            }
            if (encode_options.ppt) {
                try appendPltFromPackedPacketLengths(allocator, &out, encode_options, lengths, header_lengths);
                try appendPptPacketHeaders(allocator, &out, encode_options, lengths, header_lengths, bytes, &ppt_marker_index);
            } else if (encode_options.plt and !encode_options.ppm) {
                try appendPltFromRpclPacketLengths(allocator, &out, encode_options, lengths);
            }
            try appendMarker(allocator, &out, .sod);
            if (uses_packed_headers) {
                try appendPackedPacketBodies(allocator, &out, encode_options, lengths, header_lengths, bytes, &packet_sequence);
            } else {
                try appendRpclPackets(allocator, &out, encode_options, lengths, header_lengths, bytes, &packet_sequence);
            }
        }
    }
    try appendMarker(allocator, &out, .eoc);
    return out.toOwnedSlice(allocator);
}

/// The packet bytes of one tile-part of a merged tile stream.
fn sampledPartPacketBytes(stream: SampledTilePacketStream, part: MultiTilePacketPart) ![]const u8 {
    const start = try rpclPacketByteOffset(stream.packet_lengths, part.first_packet);
    const end = try rpclPacketByteOffset(stream.packet_lengths, part.first_packet + part.packet_count);
    if (end > stream.packet_bytes.len) return CodestreamError.InvalidCodestream;
    return stream.packet_bytes[start..end];
}

/// Single tile-part assembly for the sampled encoder. The packet count is
/// component-geometry dependent, so this bypasses the uniform packet-plan
/// check while reusing the common inline/PPT/PPM framing helpers.
fn assembleSampledSingleTileCodestream(
    allocator: std.mem.Allocator,
    input: SampledAssemblyInput,
    encode_options: LosslessOptions,
) ![]u8 {
    const main_header = try sampledMainHeaderBytes(allocator, .{
        .width = @intCast(input.width),
        .height = @intCast(input.height),
        .bit_depth = input.bit_depth,
        .component_bit_depths = input.component_bit_depths,
        .component_xrsiz = input.component_xrsiz,
        .component_yrsiz = input.component_yrsiz,
        .components = input.components,
        .image_origin_x = encode_options.image_origin_x,
        .image_origin_y = encode_options.image_origin_y,
        .tile_width = encode_options.tile_width,
        .tile_height = encode_options.tile_height,
        .tile_origin_x = encode_options.tile_origin_x,
        .tile_origin_y = encode_options.tile_origin_y,
    }, input.levels, input.bit_depth, encode_options);
    defer allocator.free(main_header);
    return writeSampledSingleTileCodestream(allocator, main_header, input.components, input.levels, .{
        .allocator = allocator,
        .tile = undefined,
        .packet_lengths = @constCast(input.packet_lengths),
        .packet_header_lengths = @constCast(input.packet_header_lengths),
        .packet_bytes = @constCast(input.packet_bytes),
    }, encode_options);
}

/// The single tile-part counterpart of `writeSampledMultiTileCodestream`.
fn writeSampledSingleTileCodestream(
    allocator: std.mem.Allocator,
    main_header: []const u8,
    components: u16,
    levels: u8,
    stream: SampledTilePacketStream,
    encode_options: LosslessOptions,
) ![]u8 {
    const input = .{
        .components = components,
        .packet_lengths = stream.packet_lengths,
        .packet_header_lengths = stream.packet_header_lengths,
        .packet_bytes = stream.packet_bytes,
    };
    if (input.packet_lengths.len != input.packet_header_lengths.len) {
        return CodestreamError.InvalidCodestream;
    }

    const uses_packed_headers = encode_options.ppm or encode_options.ppt;
    const packet_bytes = if (uses_packed_headers)
        try packedPacketBodyByteCount(encode_options, input.packet_lengths, input.packet_header_lengths)
    else
        try rpclPacketPayloadByteCount(encode_options, input.packet_lengths);
    const plt_bytes = if (encode_options.ppm or !encode_options.plt)
        0
    else if (uses_packed_headers)
        try pltBytesForPackedPacketLengths(encode_options, input.packet_lengths, input.packet_header_lengths)
    else
        try pltBytesForRpclPacketLengths(encode_options, input.packet_lengths);
    const ppt_bytes = if (encode_options.ppt)
        try pptMarkerByteCount(encode_options, input.packet_header_lengths)
    else
        0;
    const poc_bytes = if (encode_options.poc_in_tile_header)
        try pocMarkerByteCount(encode_options)
    else
        0;
    const tile_part_bytes = try std.math.add(
        usize,
        packet_bytes,
        try std.math.add(usize, plt_bytes, try std.math.add(usize, ppt_bytes, poc_bytes)),
    );
    const psot = std.math.cast(u32, try std.math.add(usize, 14, tile_part_bytes)) orelse
        return CodestreamError.ImageTooLarge;

    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(allocator);
    try appendMarker(allocator, &out, .soc);
    try out.appendSlice(allocator, main_header);
    if (encode_options.poc_records.len != 0 and !encode_options.poc_in_tile_header) {
        try appendPocForComponents(allocator, &out, levels, input.components, encode_options);
    }
    if (encode_options.tlm) try appendTlm(allocator, &out, &.{psot});

    var packed_headers: []u8 = &.{};
    defer if (packed_headers.len != 0) allocator.free(packed_headers);
    if (encode_options.ppm) {
        packed_headers = try collectPackedPacketHeaders(
            allocator,
            encode_options,
            input.packet_lengths,
            input.packet_header_lengths,
            input.packet_bytes,
        );
        try appendPpmPacketHeaderGroups(allocator, &out, &.{packed_headers});
    }

    try appendSot(allocator, &out, 0, psot, 0, 1);
    if (encode_options.poc_in_tile_header) {
        try appendPocForComponents(allocator, &out, levels, input.components, encode_options);
    }
    if (encode_options.ppt) {
        try appendPltFromPackedPacketLengths(
            allocator,
            &out,
            encode_options,
            input.packet_lengths,
            input.packet_header_lengths,
        );
        var ppt_marker_index: u16 = 0;
        try appendPptPacketHeaders(
            allocator,
            &out,
            encode_options,
            input.packet_lengths,
            input.packet_header_lengths,
            input.packet_bytes,
            &ppt_marker_index,
        );
    } else if (encode_options.plt and !encode_options.ppm) {
        try appendPltFromRpclPacketLengths(allocator, &out, encode_options, input.packet_lengths);
    }
    try appendMarker(allocator, &out, .sod);
    var packet_sequence: u16 = 0;
    if (uses_packed_headers) {
        try appendPackedPacketBodies(
            allocator,
            &out,
            encode_options,
            input.packet_lengths,
            input.packet_header_lengths,
            input.packet_bytes,
            &packet_sequence,
        );
    } else {
        try appendRpclPackets(
            allocator,
            &out,
            encode_options,
            input.packet_lengths,
            input.packet_header_lengths,
            input.packet_bytes,
            &packet_sequence,
        );
    }
    try appendMarker(allocator, &out, .eoc);
    return out.toOwnedSlice(allocator);
}

const ComponentSlices = struct {
    slices: [3][]i32,

    fn get(self: ComponentSlices, index: usize) []i32 {
        return self.slices[index];
    }
};

fn forwardComponents53(
    allocator: std.mem.Allocator,
    planes: *color.RctPlanes,
    options: LosslessOptions,
) !u8 {
    const levels = actualDwtLevels(planes.width, planes.height, options.levels);
    const slices = ComponentSlices{ .slices = .{ planes.planes[0], planes.planes[1], planes.planes[2] } };
    if (componentThreadCount(options) < 2) {
        var wavelet_workspace = try wavelet_int.Workspace.init(allocator, @max(planes.width, planes.height));
        defer wavelet_workspace.deinit();
        inline for (0..3) |component| {
            _ = try wavelet_int.forward53WithWorkspace(
                &wavelet_workspace,
                slices.get(component),
                planes.width,
                planes.height,
                levels,
            );
        }
        return levels;
    }

    // Multi-thread: distribute the three components' row/column bands across
    // all requested workers instead of capping at 3 component threads. On
    // >4-core machines the DWT is up to ~30% of a threaded encode and the
    // 3-way cap left most cores idle.
    _ = try wavelet_int.forward53Parallel(
        allocator,
        .{ slices.get(0), slices.get(1), slices.get(2) },
        planes.width,
        planes.height,
        levels,
        options.threads,
    );
    return levels;
}

/// Irreversible path front end: optional ICT (or independent DC level shifts),
/// float 9/7 DWT, then deadzone scalar quantization into the i32 coefficient
/// planes shared with the reversible pipeline.
fn forwardIrreversibleQuantizedPlanes(
    allocator: std.mem.Allocator,
    rgb: image.RgbImage,
    levels: u8,
    options: LosslessOptions,
    timings: ?*EncodeTimings,
) !color.RctPlanes {
    return forwardIrreversibleQuantizedPlanesForRegionMeasured(
        allocator,
        rgb,
        levels,
        options.quantization,
        options.mct,
        0,
        0,
        options.threads,
        timings,
    );
}

const IrreversibleForwardPlaneJob = struct {
    plane: []f32,
    quantized: []i32,
    width: usize,
    height: usize,
    levels: u8,
    x0: u32,
    y0: u32,
    bands: []const subband.Band,
    deltas: []const f64,
    result: anyerror!void = {},
};

fn irreversibleForwardPlaneWorker(job: *IrreversibleForwardPlaneJob) void {
    job.result = irreversibleForwardPlane(job);
}

fn irreversibleForwardPlane(job: *IrreversibleForwardPlaneJob) anyerror!void {
    const done = try wavelet.forward2DOrigin(
        std.heap.smp_allocator,
        job.plane,
        job.width,
        job.height,
        job.levels,
        .irreversible_9_7,
        job.x0,
        job.y0,
    );
    if (done != job.levels) return CodestreamError.InvalidCodestream;
    for (job.bands, job.deltas) |band, delta| {
        quantizeBandRegion(job.plane, job.quantized, job.width, band.rect, delta);
    }
}

/// Quantization of one plane's rows `row_begin..row_end` for the intra-plane
/// parallel DWT path, where the 9/7 transform already ran jointly across all
/// planes; the integers overwrite the floats they come from.
const IrreversibleQuantizeRowsJob = struct {
    plane: []f32,
    width: usize,
    row_begin: usize,
    row_end: usize,
    bands: []const subband.Band,
    deltas: []const f64,

    fn work(job: *IrreversibleQuantizeRowsJob) void {
        for (job.bands, job.deltas) |band, delta| {
            const top = @max(band.rect.y, job.row_begin);
            const bottom = @min(band.rect.y + band.rect.height, job.row_end);
            if (top >= bottom or band.rect.width == 0) continue;
            const rows = subband.Rect{ .x = band.rect.x, .y = top, .width = band.rect.width, .height = bottom - top };
            quantizeBandRegion(job.plane, @as([*]i32, @ptrCast(job.plane.ptr))[0..job.plane.len], job.width, rows, delta);
        }
    }
};

/// Quantizes the transformed planes in place, in row ranges spread over up
/// to `thread_count` threads of the shared pool (inline when it is busy).
fn quantizeIrreversiblePlanesInPlace(
    allocator: std.mem.Allocator,
    planes: []const []f32,
    width: usize,
    height: usize,
    bands: []const subband.Band,
    deltas: []const f64,
    thread_count: u8,
) !void {
    const ranges_per_plane = @max(1, @min(@as(usize, thread_count), height));
    const jobs = try allocator.alloc(IrreversibleQuantizeRowsJob, planes.len * ranges_per_plane);
    defer allocator.free(jobs);
    for (planes, 0..) |plane, plane_index| {
        for (0..ranges_per_plane) |range| {
            jobs[plane_index * ranges_per_plane + range] = .{
                .plane = plane,
                .width = width,
                .row_begin = height * range / ranges_per_plane,
                .row_end = height * (range + 1) / ranges_per_plane,
                .bands = bands,
                .deltas = deltas,
            };
        }
    }
    if (!worker_pool.runJobsOn(thread_count, IrreversibleQuantizeRowsJob, jobs, IrreversibleQuantizeRowsJob.work)) {
        for (jobs) |*job| job.work();
    }
}

fn forwardIrreversibleQuantizedPlanesForRegion(
    allocator: std.mem.Allocator,
    rgb: image.RgbImage,
    levels: u8,
    quantization: QuantizationStyle,
    mct: MultipleComponentTransform,
    x0: u32,
    y0: u32,
    thread_count: u8,
) !color.RctPlanes {
    return forwardIrreversibleQuantizedPlanesForRegionMeasured(allocator, rgb, levels, quantization, mct, x0, y0, thread_count, null);
}

/// Measured variant of the irreversible front end: the colour/level-shift stage
/// accounts to `color_transform_ns` and the fused per-plane 9/7 DWT + deadzone
/// quantization jobs account to `wavelet_ns`, so `--timings` no longer
/// reports the whole front end as MCT with an empty DWT row.
fn forwardIrreversibleQuantizedPlanesForRegionMeasured(
    allocator: std.mem.Allocator,
    rgb: image.RgbImage,
    levels: u8,
    quantization: QuantizationStyle,
    mct: MultipleComponentTransform,
    x0: u32,
    y0: u32,
    thread_count: u8,
    timings: ?*EncodeTimings,
) !color.RctPlanes {
    const color_start = monotonicNs();
    var ict = if (mct == .none)
        try color.forwardNoTransformFloat(allocator, rgb)
    else if (thread_count > 1)
        try color.forwardIctThreaded(allocator, rgb, thread_count)
    else
        try color.forwardIct(allocator, rgb);
    defer ict.deinit();
    if (timings) |t| t.color_transform_ns += elapsedNs(color_start);

    const x1 = std.math.add(u32, x0, std.math.cast(u32, ict.width) orelse return CodestreamError.ImageTooLarge) catch
        return CodestreamError.ImageTooLarge;
    const y1 = std.math.add(u32, y0, std.math.cast(u32, ict.height) orelse return CodestreamError.ImageTooLarge) catch
        return CodestreamError.ImageTooLarge;
    const bands = try subband.makeBandsForRegion(allocator, x0, y0, x1, y1, levels);
    defer allocator.free(bands);
    const deltas = try allocator.alloc(f64, bands.len);
    defer allocator.free(deltas);
    for (bands, deltas) |band, *delta| {
        delta.* = irreversibleBandDelta(
            rgb.bit_depth,
            band.kind,
            try irreversibleBandStepSizeFor(quantization, rgb.bit_depth, band.kind, band.level, levels),
        );
    }

    const wavelet_start = monotonicNs();
    if (thread_count > 1) {
        // Intra-plane parallel DWT: one joint 9/7 transform over the three
        // planes with row/column bands spread across all `thread_count`
        // workers, then quantization in row ranges on all of them. The
        // per-plane job path below caps the DWT at three threads and starves
        // wider machines. The per-column/per-row arithmetic is unchanged, so
        // streams stay bit-identical.
        const done = try wavelet.forward97Parallel(
            std.heap.smp_allocator,
            .{ ict.planes[0], ict.planes[1], ict.planes[2] },
            ict.width,
            ict.height,
            levels,
            x0,
            y0,
            thread_count,
        );
        if (done != levels) return CodestreamError.InvalidCodestream;
        // Each sample is quantized into its own slot, so the integer planes
        // reuse the floating-point ones instead of 4 bytes per sample more.
        try quantizeIrreversiblePlanesInPlace(allocator, ict.planes[0..3], ict.width, ict.height, bands, deltas, thread_count);
        const planes = try allocator.alloc([]i32, 3);
        for (planes, ict.planes[0..3]) |*plane, source| plane.* = @as([*]i32, @ptrCast(source.ptr))[0..source.len];
        var out = color.RctPlanes{
            .allocator = allocator,
            .width = ict.width,
            .height = ict.height,
            .bit_depth = rgb.bit_depth,
            .planes = planes,
        };
        @memset(out.component_bit_depths[0..3], rgb.bit_depth);
        @memset(out.component_widths[0..3], ict.width);
        @memset(out.component_heights[0..3], ict.height);
        // The planes now belong to `out`; `ict` frees only its plane list.
        allocator.free(ict.planes);
        ict.planes = &.{};
        if (timings) |t| t.wavelet_ns += elapsedNs(wavelet_start);
        return out;
    }

    var out = try color.RctPlanes.init(allocator, ict.width, ict.height, rgb.bit_depth, 3);
    errdefer out.deinit();
    const y = out.planes[0];
    const cb = out.planes[1];
    const cr = out.planes[2];
    {
        // Serial/tile-worker path: each component's 9/7 DWT and deadzone
        // quantization is independent, so the three planes run as fused
        // component jobs (same pattern as the 5/3 path).
        var jobs = [3]IrreversibleForwardPlaneJob{
            .{ .plane = ict.planes[0], .quantized = y, .width = ict.width, .height = ict.height, .levels = levels, .x0 = x0, .y0 = y0, .bands = bands, .deltas = deltas },
            .{ .plane = ict.planes[1], .quantized = cb, .width = ict.width, .height = ict.height, .levels = levels, .x0 = x0, .y0 = y0, .bands = bands, .deltas = deltas },
            .{ .plane = ict.planes[2], .quantized = cr, .width = ict.width, .height = ict.height, .levels = levels, .x0 = x0, .y0 = y0, .bands = bands, .deltas = deltas },
        };
        try runComponentJobs(IrreversibleForwardPlaneJob, allocator, jobs[0..], thread_count, irreversibleForwardPlaneWorker);
    }
    if (timings) |t| t.wavelet_ns += elapsedNs(wavelet_start);

    return out;
}

/// Tile front end for the irreversible multi-tile path: extracts the tile
/// region, then runs the same colour front end + 9/7 + deadzone quantization the
/// single-tile path uses, retaining the tile's reference-grid lifting parity.
const IrreversibleTileFrontEndContext = struct {
    quantization: QuantizationStyle,
    mct: MultipleComponentTransform,
};

fn buildIrreversibleQuantizedTile(
    context: *const anyopaque,
    allocator: std.mem.Allocator,
    source: image.RgbImage,
    tile: tile_grid.Tile,
    levels: u8,
) anyerror!tile_pipeline.RctTile {
    const ctx: *const IrreversibleTileFrontEndContext = @ptrCast(@alignCast(context));
    var rgb_tile = try tile_grid.extractRgbTile(allocator, source, tile.rect);
    defer rgb_tile.deinit();
    // Tiles already run on parallel tile workers; keep the per-plane stage
    // serial here to avoid oversubscription.
    const planes = try forwardIrreversibleQuantizedPlanesForRegion(
        allocator,
        rgb_tile,
        levels,
        ctx.quantization,
        ctx.mct,
        tile.rect.x0,
        tile.rect.y0,
        1,
    );
    return .{ .tile = tile, .planes = planes };
}

/// Per-band nominal bitplane (Mb) table for irreversible tiles, indexed
/// [band_level][kind]: Mb derives from the signalled epsilon_b (E-2), which
/// is identical for every tile because the step tables depend only on the
/// global bit depth, quantization style, and level count.
fn irreversibleNominalBitplaneTable(
    bit_depth: u8,
    levels: u8,
    guard_bits: u8,
    quantization: QuantizationStyle,
) ![33][4]u8 {
    var table: [33][4]u8 = @splat(.{ 0, 0, 0, 0 });
    if (levels > 32) return CodestreamError.UnsupportedPayload;
    var level: u8 = 1;
    while (level <= levels) : (level += 1) {
        inline for (.{ subband.Kind.hl, subband.Kind.lh, subband.Kind.hh }) |kind| {
            table[level][@backingInt(kind)] = try bandNominalBitplanesForTransform(
                bit_depth,
                kind,
                level,
                .irreversible_9_7,
                guard_bits,
                quantization,
                levels,
            );
        }
    }
    table[levels][@backingInt(subband.Kind.ll)] = try bandNominalBitplanesForTransform(
        bit_depth,
        .ll,
        levels,
        .irreversible_9_7,
        guard_bits,
        quantization,
        levels,
    );
    return table;
}

/// Per-band PCRD distortion weight table for irreversible tiles, indexed
/// [band_level][kind]: `(reconstruction step delta x 9/7 synthesis norm)^2`
/// converts quantized-coefficient squared error into weighted reconstruction
/// squared error (ISO 15444-1 J.14). Identical for every tile because the
/// step tables and norms depend only on the global bit depth, quantization
/// style, and level count. Mirrors the single-tile pcrdBandWeight.
fn irreversibleBandWeightTable(
    bit_depth: u8,
    levels: u8,
    quantization: QuantizationStyle,
) ![33][4]f64 {
    var table: [33][4]f64 = @splat(.{ 0, 0, 0, 0 });
    if (levels > 32) return CodestreamError.UnsupportedPayload;
    const kinds = [_]subband.Kind{ .ll, .hl, .lh, .hh };
    var level: u8 = 1;
    while (level <= levels) : (level += 1) {
        for (kinds) |kind| {
            if (kind == .ll and level != levels) continue;
            const opj_level: usize = if (kind == .ll) level else @as(usize, level) - 1;
            const orient: usize = @backingInt(kind);
            const step = try irreversibleBandStepSizeFor(quantization, bit_depth, kind, level, levels);
            const weighted = irreversiblePcrdDelta(bit_depth, kind, step) * dwt97Norm(opj_level, orient);
            table[level][orient] = weighted * weighted;
        }
    }
    return table;
}

fn quantizeBandRegion(src: []const f32, dst: []i32, stride: usize, rect: subband.Rect, delta: f64) void {
    var row: usize = 0;
    while (row < rect.height) : (row += 1) {
        const base = (rect.y + row) * stride + rect.x;
        var col: usize = 0;
        while (col < rect.width) : (col += 1) {
            const value: f64 = src[base + col];
            const magnitude = @floor(@abs(value) / delta);
            const quantized: i32 = @intFromFloat(@min(magnitude, 2147483647.0));
            dst[base + col] = if (value < 0) -quantized else quantized;
        }
    }
}

const IrreversibleMidpointRule = enum {
    /// Every non-zero coefficient was decoded through bitplane zero.
    all,
    /// Only coefficients that became significant in the final significance
    /// propagation pass of bitplane zero (magnitude exactly one) were.
    unit_magnitudes,
    /// No coefficient reached bitplane zero.
    none,
};

/// T1 already reconstructs a coefficient last decoded at bitplane p >= 1 at the
/// midpoint of its uncertainty interval, m * 2^p + 2^(p-1); at bitplane zero
/// that half step is fractional and cannot be stored, so dequantization adds
/// it as `+ 0.5`. Applying `+ 0.5` to a coefficient that stopped at p >= 1
/// counts the midpoint twice. Which coefficients reached bitplane zero follows
/// from the block's last coding pass (ISO D.3): cleanup at the top plane, then
/// significance propagation, magnitude refinement, and cleanup for each lower
/// plane.
fn strictIrreversibleMidpointRule(block: StrictPacketBlock) IrreversibleMidpointRule {
    const passes = block.cumulative_passes;
    const bitplanes = block.encoded_bitplanes;
    if (passes == 0 or bitplanes == 0) return .none;
    if (passes == 1) return if (bitplanes == 1) .all else .none;
    const after_first = passes - 2;
    const planes_below_top = after_first / 3;
    if (planes_below_top + 2 > bitplanes) return .all;
    const plane = bitplanes - 2 - planes_below_top;
    if (plane != 0) return .none;
    return switch (after_first % 3) {
        // Significance propagation at plane zero: refinement of previously
        // significant coefficients never ran, so only the newly significant
        // ones (magnitude exactly one) reached plane zero.
        0 => .unit_magnitudes,
        // Refinement or cleanup at plane zero: every non-zero coefficient was
        // visited there. Coefficients a missing cleanup would have made
        // significant are still zero and take no offset either way.
        else => .all,
    };
}

fn removeUnearnedMidpointOffsets(job: *IrreversibleInversePlaneJob, blocks: []const StrictPacketBlock) !void {
    for (blocks) |block| {
        const rule = strictIrreversibleMidpointRule(block);
        if (rule == .all) continue;
        if (block.band_index >= job.bands.len) return CodestreamError.InvalidCodestream;
        const band = job.bands[block.band_index];
        if (!strictBandRequiredForReduction(band, job.reduction)) continue;
        const half_step: f32 = @floatCast(job.deltas[block.band_index] * 0.5);
        const end_x = try std.math.add(usize, block.rect.x, block.rect.width);
        const end_y = try std.math.add(usize, block.rect.y, block.rect.height);
        if (end_x > job.width or end_y > job.height) return CodestreamError.InvalidCodestream;
        var y = block.rect.y;
        while (y < end_y) : (y += 1) {
            var x = block.rect.x;
            while (x < end_x) : (x += 1) {
                const index = y * job.width + x;
                const q = job.quantized[index];
                if (q == 0) continue;
                if (rule == .unit_magnitudes and @abs(q) == 1) continue;
                job.plane[index] -= if (q < 0) -half_step else half_step;
            }
        }
    }
}

fn dequantizeBandRegion(src: []const i32, dst: []f32, stride: usize, rect: subband.Rect, delta: f64) void {
    const lanes = 8;
    const QuantVector = @Vector(lanes, i32);
    const WideVector = @Vector(lanes, f64);
    const SampleVector = @Vector(lanes, f32);
    const zero: QuantVector = @splat(0);
    const half: WideVector = @splat(0.5);
    const step: WideVector = @splat(delta);
    var row: usize = 0;
    while (row < rect.height) : (row += 1) {
        const base = (rect.y + row) * stride + rect.x;
        var col: usize = 0;
        // The scalar rule below, lane by lane in the same f64 arithmetic.
        while (col + lanes <= rect.width) : (col += lanes) {
            const q: QuantVector = src[base + col ..][0..lanes].*;
            const magnitude: WideVector = @floatFromInt(@abs(q));
            const value = (magnitude + half) * step;
            const signed: SampleVector = @floatCast(@select(f64, q < zero, -value, value));
            dst[base + col ..][0..lanes].* = @select(f32, q == zero, @as(SampleVector, @splat(0)), signed);
        }
        while (col < rect.width) : (col += 1) {
            const q = src[base + col];
            if (q == 0) {
                dst[base + col] = 0;
                continue;
            }
            const magnitude = @as(f64, @floatFromInt(@abs(q))) + 0.5;
            const value = magnitude * delta;
            dst[base + col] = @floatCast(if (q < 0) -value else value);
        }
    }
}

fn acceptsAll(context: *anyopaque, target: usize, progress: f64) bool {
    _ = context;
    _ = target;
    _ = progress;
    return true;
}

/// `StrictComponentFinisher` running the serial inverse 5/3 on a decoded
/// plane (equal to the parallel transform byte for byte).
const StrictInverse53Finisher = struct {
    width: usize,
    height: usize,
    levels: u8,

    fn finisher(self: *StrictInverse53Finisher, finished: []std.atomic.Value(bool)) StrictComponentFinisher {
        return .{
            .context = self,
            .accepts = acceptsAll,
            .finish = finish,
            // The last plane completes when the pool drains; it is cheaper
            // on all DWT workers afterwards than on one worker at the end.
            .target_limit = finished.len - 1,
            .finished = finished,
        };
    }

    fn finish(context: *anyopaque, target: usize, plane: []i32) anyerror!void {
        _ = target;
        const self: *StrictInverse53Finisher = @ptrCast(@alignCast(context));
        var workspace = try wavelet_int.Workspace.init(std.heap.smp_allocator, @max(self.width, self.height));
        defer workspace.deinit();
        try wavelet_int.inverse53WithWorkspace(&workspace, plane, self.width, self.height, self.levels);
    }
};

fn inverseComponents53(
    allocator: std.mem.Allocator,
    slices: ComponentSlices,
    width: usize,
    height: usize,
    levels: u8,
    x0: u32,
    y0: u32,
    options: DecodeOptions,
) !void {
    if (x0 != 0 or y0 != 0) {
        var wavelet_workspace = try wavelet_int.Workspace.init(allocator, @max(width, height));
        defer wavelet_workspace.deinit();
        inline for (0..3) |component| {
            try wavelet_int.inverse53WithWorkspaceOrigin(
                &wavelet_workspace,
                slices.get(component),
                width,
                height,
                levels,
                x0,
                y0,
            );
        }
        return;
    }
    if (componentThreadCountFor(options.threads) < 2) {
        var wavelet_workspace = try wavelet_int.Workspace.init(allocator, @max(width, height));
        defer wavelet_workspace.deinit();
        inline for (0..3) |component| {
            try wavelet_int.inverse53WithWorkspace(
                &wavelet_workspace,
                slices.get(component),
                width,
                height,
                levels,
            );
        }
        return;
    }

    // Multi-thread: full-core parallel inverse DWT (see forwardComponents53).
    try wavelet_int.inverse53Parallel(
        allocator,
        .{ slices.get(0), slices.get(1), slices.get(2) },
        width,
        height,
        levels,
        options.threads,
    );
}

fn runComponentJobs(
    comptime Job: type,
    allocator: std.mem.Allocator,
    jobs: []Job,
    thread_count: u8,
    comptime worker: fn (*Job) void,
) !void {
    if (jobs.len == 0 or thread_count == 0) {
        return CodestreamError.InvalidCodestream;
    }
    const active_threads: usize = @min(@as(usize, thread_count), jobs.len);
    const spawn_count = active_threads - 1;
    const threads = try allocator.alloc(std.Thread, spawn_count);
    defer allocator.free(threads);
    var spawned: usize = 0;
    while (spawned < spawn_count) : (spawned += 1) {
        threads[spawned] = std.Thread.spawn(.{}, worker, .{&jobs[spawned]}) catch |err| {
            for (threads[0..spawned]) |thread| thread.join();
            return err;
        };
    }

    var component = spawned;
    while (component < jobs.len) : (component += 1) {
        worker(&jobs[component]);
    }

    for (threads[0..spawned]) |thread| thread.join();
    for (jobs) |job| try job.result;
}

test "component job runner exceeds the legacy slot count" {
    const Job = struct {
        completed: bool = false,
        result: anyerror!void = {},

        fn run(job: *@This()) void {
            job.completed = true;
        }
    };
    var jobs: [max_codestream_components + 3]Job = @splat(.{});
    try runComponentJobs(Job, std.testing.allocator, &jobs, 8, Job.run);
    for (jobs) |job| try std.testing.expect(job.completed);
}

fn actualDwtLevels(width: usize, height: usize, requested_levels: u8) u8 {
    var cur_width = width;
    var cur_height = height;
    var done: u8 = 0;
    while (done < requested_levels and (cur_width > 1 or cur_height > 1)) : (done += 1) {
        cur_width = (cur_width + 1) / 2;
        cur_height = (cur_height + 1) / 2;
    }
    return done;
}

fn componentThreadCount(options: LosslessOptions) u8 {
    return componentThreadCountFor(options.threads);
}

fn componentThreadCountFor(thread_count: u8) u8 {
    return @min(thread_count, 3);
}

const ComponentPayloadJob = struct {
    component_index: u8,
    bands: []const subband.Band,
    blocks: []const subband.CodeBlock,
    catalog: []const RpclShadowBlock,
    options: LosslessOptions,
    bytes: []u8 = &.{},
    result: anyerror!void = {},

    fn deinit(self: *ComponentPayloadJob) void {
        std.heap.smp_allocator.free(self.bytes);
        self.bytes = &.{};
    }
};

const ComponentCatalogJob = struct {
    plane: []const i32,
    stride: usize,
    bands: []const subband.Band,
    blocks: []const subband.CodeBlock,
    nominal_bitplanes: u8,
    options: LosslessOptions,
    include_bitplane_payload: bool,
    catalog: ComponentRpclShadowCatalog = undefined,
    initialized: bool = false,
    result: anyerror!void = {},

    fn deinit(self: *ComponentCatalogJob) void {
        if (self.initialized) {
            self.catalog.deinit();
            self.initialized = false;
        }
    }
};

const ComponentCatalogBlockJob = struct {
    allocator: std.mem.Allocator,
    plane: []const i32,
    stride: usize,
    bands: []const subband.Band,
    blocks: []const subband.CodeBlock,
    catalog_blocks: []RpclShadowBlock,
    next_block: *std.atomic.Value(usize),
    block_order: []const usize,
    nominal_bitplanes: u8,
    options: LosslessOptions,
    include_bitplane_payload: bool,
    initialized: std.ArrayList(usize) = .empty,
    result: anyerror!void = {},

    fn deinit(self: *ComponentCatalogBlockJob) void {
        for (self.initialized.items) |block_index| {
            self.catalog_blocks[block_index].deinit(self.allocator);
        }
        self.initialized.deinit(self.allocator);
        self.initialized = .empty;
    }

    fn release(self: *ComponentCatalogBlockJob) void {
        self.initialized.clearRetainingCapacity();
    }
};

