/// Bounded effective coding state carried by the first tile-part header of a
/// tile. Progression, layers, MCT, and component sampling remain common, while
/// tile COD/COC may replace decomposition, precinct, code-block, style, and
/// transform state and tile QCD/QCC supplies the matching quantization table.
const StrictTileCodingOverride = struct {
    saw_cod: bool = false,
    saw_qcd: bool = false,
    coding: StrictComponentCoding = .{},
    qcd: StrictQcdInfo = empty_strict_qcd_info,
    components: std.ArrayList(StrictTileComponentOverride) = .empty,

    fn deinit(self: *StrictTileCodingOverride, allocator: std.mem.Allocator) void {
        self.components.deinit(allocator);
        self.* = undefined;
    }
};

const StrictTileComponentOverride = struct {
    component: u16,
    saw_coc: bool = false,
    saw_qcc: bool = false,
    saw_rgn: bool = false,
    coding: StrictComponentCoding = .{},
    qcd: StrictQcdInfo = empty_strict_qcd_info,
    roi_shift: u8 = 0,
};

fn strictTileOverrideChangesCoding(tile_override: StrictTileCodingOverride) bool {
    if (tile_override.saw_cod or tile_override.saw_qcd) return true;
    for (tile_override.components.items) |component_override| {
        if (component_override.saw_coc or component_override.saw_qcc) return true;
    }
    return false;
}

fn strictComponentCodingEqualIgnoringRoi(a: StrictComponentCoding, b: StrictComponentCoding) bool {
    var left = a;
    var right = b;
    left.roi_shift = 0;
    right.roi_shift = 0;
    return std.meta.eql(left, right);
}

